def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--root",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--a1-r2-dir",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--a3-dir",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--a4-dir",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--b0-r1b-dir",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--loader-path",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--model-path",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--output-dir",
        type=Path,
        required=True,
    )
    args = parser.parse_args()

    root_input = args.root.expanduser()
    root = root_input.resolve()
    a1_r2_dir = args.a1_r2_dir.expanduser().resolve()
    a3_dir = args.a3_dir.expanduser().resolve()
    a4_dir = args.a4_dir.expanduser().resolve()
    b0_r1b_dir = (
        args.b0_r1b_dir.expanduser().resolve()
    )
    loader_path = (
        args.loader_path.expanduser().resolve()
    )
    model_path = (
        args.model_path.expanduser().resolve()
    )
    output_dir = (
        args.output_dir.expanduser().resolve()
    )

    if output_dir.exists():
        print(
            f"STOP: output already exists: "
            f"{output_dir}",
            file=sys.stderr,
        )
        return 2
    output_dir.mkdir(parents=True)

    failures: list[str] = []
    warnings: list[str] = []

    paths = {
        "a1_r2_report": (
            a1_r2_dir
            / "V5_P2_A1_R2_PAIR_ALIGNED_WINDOW_CONTRACT.json"
        ),
        "a1_r2_lock": (
            a1_r2_dir
            / "V5_P2_A1_R2_PAIR_ALIGNED_WINDOW_CONTRACT_LOCK.json"
        ),
        "pair_manifest": (
            a1_r2_dir
            / "V5_P2_A1_R2_PAIR_ALIGNED_WINDOW_MANIFEST.csv"
        ),
        "a3_report": (
            a3_dir
            / "V5_P2_A3_PAIR_ALIGNED_PRIMARY58_LOADER_CONTRACT.json"
        ),
        "a3_lock": (
            a3_dir
            / "V5_P2_A3_PAIR_ALIGNED_PRIMARY58_LOADER_CONTRACT_LOCK.json"
        ),
        "a4_report": (
            a4_dir
            / "V5_P2_A4_LOADER_INTEGRATION_AND_TINY_OVERFIT.json"
        ),
        "a4_lock": (
            a4_dir
            / "V5_P2_A4_LOADER_INTEGRATION_AND_TINY_OVERFIT_LOCK.json"
        ),
        "b0_r1b_report": (
            b0_r1b_dir
            / "V5_P2_B0_R1B_K3_COUNT_AND_ROLE_MASK_SEMANTICS_AUDIT.json"
        ),
        "b0_r1b_lock": (
            b0_r1b_dir
            / "V5_P2_B0_R1B_K3_COUNT_AND_ROLE_MASK_SEMANTICS_AUDIT_LOCK.json"
        ),
        "loader": loader_path,
        "model": model_path,
    }

    for name, path in paths.items():
        if not path.is_file():
            failures.append(
                f"missing prerequisite {name}: {path}"
            )

    if not (
        root
        / "runs"
        / "train"
    ).is_dir():
        failures.append(
            "missing runs/train"
        )

    if failures:
        report = {
            "stage": STAGE,
            "status": "HOLD",
            "failures": failures,
            "warnings": warnings,
            "training_performed": False,
            "validation_tensor_contents_accessed": False,
            "test_directory_enumerated": False,
            "test_tensor_contents_accessed": False,
        }
        write_json(
            output_dir / f"{STAGE}.json",
            report,
        )
        atomic_write(
            output_dir / f"{STAGE}_HOLD",
            f"{STAGE}_HOLD\n",
        )
        print(f"{STAGE}_HOLD")
        return 1

    a1_report = load_json(
        paths["a1_r2_report"]
    )
    a1_lock = load_json(
        paths["a1_r2_lock"]
    )
    a3_report = load_json(
        paths["a3_report"]
    )
    a3_lock = load_json(
        paths["a3_lock"]
    )
    a4_report = load_json(
        paths["a4_report"]
    )
    a4_lock = load_json(
        paths["a4_lock"]
    )
    b0_r1b_report = load_json(
        paths["b0_r1b_report"]
    )
    b0_r1b_lock = load_json(
        paths["b0_r1b_lock"]
    )

    for label, report, lock, report_path in (
        (
            "A1-R2",
            a1_report,
            a1_lock,
            paths["a1_r2_report"],
        ),
        (
            "A3",
            a3_report,
            a3_lock,
            paths["a3_report"],
        ),
        (
            "A4",
            a4_report,
            a4_lock,
            paths["a4_report"],
        ),
        (
            "B0-R1B",
            b0_r1b_report,
            b0_r1b_lock,
            paths["b0_r1b_report"],
        ),
    ):
        if report.get("status") != "COMPLETE":
            failures.append(
                f"{label} status is not COMPLETE"
            )
        if (
            lock.get("report_sha256")
            != sha256_file(report_path)
        ):
            failures.append(
                f"{label} report SHA mismatch"
            )
        if (
            report.get(
                "security_boundary",
                {},
            ).get(
                "test_tensor_contents_accessed"
            )
            is not False
        ):
            failures.append(
                f"{label} does not certify untouched test"
            )

    expected_b0_r1b_decision = (
        "RESOLVE_B0_HOLD_AS_K3_OMISSION_AND_"
        "ROLE_MASK_SEMANTIC_MISCLASSIFICATION_"
        "REQUIRE_COUNT_HEAD_3_TO_4_AND_REPEAT_A4"
    )
    if (
        b0_r1b_lock.get("decision")
        != expected_b0_r1b_decision
    ):
        failures.append(
            "B0-R1B did not authorize count-head "
            "expansion and A4 repeat"
        )
    if b0_r1b_lock.get(
        "observed_categories"
    ) != [1, 2, 3, 4]:
        failures.append(
            "B0-R1B observed categories changed"
        )
    if b0_r1b_lock.get(
        "observed_active_counts"
    ) != [1, 2, 3, 4]:
        failures.append(
            "B0-R1B observed active counts changed"
        )
    if b0_r1b_lock.get(
        "role_mask_semantics"
    ) != "bitfield3_source1_transit2_victim4":
        failures.append(
            "B0-R1B role_mask semantics changed"
        )
    if b0_r1b_lock.get(
        "current_count_logits"
    ) != 3:
        failures.append(
            "B0-R1B current count logits changed"
        )
    if b0_r1b_lock.get(
        "required_count_logits"
    ) != 4:
        failures.append(
            "B0-R1B required count logits changed"
        )
    if b0_r1b_lock.get(
        "projected_parameter_count"
    ) != EXPECTED_PARAMETER_COUNT:
        failures.append(
            "B0-R1B projected parameter count changed"
        )

    if (
        a1_lock.get("pair_manifest_sha256")
        != sha256_file(paths["pair_manifest"])
    ):
        failures.append(
            "A1-R2 pair-manifest SHA mismatch"
        )
    if (
        a3_lock.get("loader_sha256")
        != sha256_file(paths["loader"])
    ):
        failures.append(
            "A3 loader SHA mismatch"
        )
    if a3_lock.get(
        "test_constructor_rejected"
    ) is not True:
        failures.append(
            "A3 test-constructor rejection changed"
        )
    if a4_lock.get(
        "audit_weights_saved"
    ) is not False:
        failures.append(
            "historical A4 unexpectedly saved weights"
        )

    if failures:
        report = {
            "stage": STAGE,
            "status": "HOLD",
            "failures": failures,
            "warnings": warnings,
            "training_performed": False,
            "validation_tensor_contents_accessed": False,
            "test_directory_enumerated": False,
            "test_tensor_contents_accessed": False,
        }
        write_json(
            output_dir / f"{STAGE}.json",
            report,
        )
        atomic_write(
            output_dir / f"{STAGE}_HOLD",
            f"{STAGE}_HOLD\n",
        )
        print(f"{STAGE}_HOLD")
        for failure in failures:
            print("FAIL:", failure)
        return 1

    set_seed(SEED)

    loader_module = import_module(
        loader_path,
        "v5_p2_pair_aligned_loader_b0_r2",
    )
    model_module = import_module(
        model_path,
        "v5_p2_b3_count4_b0_r2",
    )

    DatasetClass = (
        loader_module
        .V5P2PairAlignedPrimary58Dataset
    )
    ModelClass = (
        model_module
        .P2B3Conv1DOnlyCount4
    )

    train_dataset = DatasetClass(
        root=root,
        split="train",
        pair_manifest=paths["pair_manifest"],
    )

    pair_bases: dict[
        str,
        list[int],
    ] = defaultdict(list)

    for base in range(
        0,
        len(train_dataset._index),
        2,
    ):
        attack_entry = train_dataset._index[base]
        control_entry = train_dataset._index[
            base + 1
        ]

        if (
            attack_entry.mode != "attack"
            or control_entry.mode != "control"
            or attack_entry.pair_key
            != control_entry.pair_key
            or attack_entry.start
            != control_entry.start
            or attack_entry.target
            != control_entry.target
        ):
            failures.append(
                f"train pair-index adjacency failed "
                f"at base={base}"
            )
            continue

        pair_bases[
            attack_entry.pair_key
        ].append(base)

    selected_by_category: dict[
        int,
        list[dict[str, Any]],
    ] = defaultdict(list)

    for pair_key in sorted(pair_bases):
        category = category_from_pair_key(
            pair_key
        )
        if category not in {
            1,
            2,
            3,
            4,
        }:
            continue
        if len(
            selected_by_category[category]
        ) >= 2:
            continue

        bases = pair_bases[pair_key]
        first_entry = train_dataset._index[
            bases[0]
        ]
        attack_run = train_dataset._load_run(
            first_entry.file_path
        )

        active_bases = [
            base
            for base in bases
            if int(
                attack_run["y_attack"][
                    train_dataset._index[
                        base
                    ].target
                ].item()
            )
            == 1
        ]
        if not active_bases:
            continue

        base = active_bases[-1]
        attack_entry = train_dataset._index[
            base
        ]
        control_entry = train_dataset._index[
            base + 1
        ]

        attack_item = train_dataset[base]
        control_item = train_dataset[
            base + 1
        ]

        raw_count = int(
            attack_item[
                "y_attacker_count"
            ].item()
        )
        source_count = int(
            attack_item[
                "y_source"
            ].sum().item()
        )

        if float(
            attack_item["y_attack"].item()
        ) != 1.0:
            failures.append(
                f"{pair_key}: selected attack is inactive"
            )
            continue
        if float(
            control_item["y_attack"].item()
        ) != 0.0:
            failures.append(
                f"{pair_key}: matched control is active"
            )
            continue
        if raw_count != category:
            failures.append(
                f"{pair_key}: attack count={raw_count}, "
                f"category={category}"
            )
            continue
        if source_count != category:
            failures.append(
                f"{pair_key}: source count="
                f"{source_count}, category={category}"
            )
            continue
        if int(
            control_item[
                "y_attacker_count"
            ].item()
        ) != 0:
            failures.append(
                f"{pair_key}: control count is nonzero"
            )
            continue

        selected_by_category[
            category
        ].append(
            {
                "category": category,
                "pair_key": pair_key,
                "attack_index": base,
                "control_index": base + 1,
                "window_start": (
                    attack_entry.start
                ),
                "window_target": (
                    attack_entry.target
                ),
                "common_length": (
                    attack_entry.common_length
                ),
                "raw_positive_attacker_count": (
                    raw_count
                ),
            }
        )

        if all(
            len(
                selected_by_category[
                    category_value
                ]
            )
            >= 2
            for category_value in (
                1,
                2,
                3,
                4,
            )
        ):
            break

    for category in (1, 2, 3, 4):
        if len(
            selected_by_category[category]
        ) != 2:
            failures.append(
                f"selected "
                f"{len(selected_by_category[category])} "
                f"active K{category} pairs, expected 2"
            )

    selected_pairs = [
        record
        for category in (1, 2, 3, 4)
        for record in selected_by_category[
            category
        ]
    ]

    selected_indices: list[int] = []
    for record in selected_pairs:
        selected_indices.extend(
            [
                record["attack_index"],
                record["control_index"],
            ]
        )

    if len(selected_pairs) != 8:
        failures.append(
            f"selected pair count="
            f"{len(selected_pairs)}, expected 8"
        )
    if len(selected_indices) != 16:
        failures.append(
            f"tiny item count="
            f"{len(selected_indices)}, expected 16"
        )

    if failures:
        report = {
            "stage": STAGE,
            "status": "HOLD",
            "failures": failures,
            "warnings": warnings,
            "selection": selected_pairs,
            "training_performed": False,
            "validation_tensor_contents_accessed": False,
            "test_directory_enumerated": False,
            "test_tensor_contents_accessed": False,
        }
        write_json(
            output_dir / f"{STAGE}.json",
            report,
        )
        atomic_write(
            output_dir / f"{STAGE}_HOLD",
            f"{STAGE}_HOLD\n",
        )
        print(f"{STAGE}_HOLD")
        for failure in failures:
            print("FAIL:", failure)
        return 1

    subset = Subset(
        train_dataset,
        selected_indices,
    )
    batch_loader = DataLoader(
        subset,
        batch_size=len(subset),
        shuffle=False,
        num_workers=0,
        drop_last=False,
    )
    batch = next(iter(batch_loader))

    expected_batch_keys = {
        "x",
        "physical_port_mask",
        "y_attack",
        "y_attacker_count",
        "y_source",
        "y_transit",
        "y_victim",
        "y_attack_path",
        "role_mask",
    }
    if set(batch) != expected_batch_keys:
        failures.append(
            f"collated keys={sorted(batch)}, "
            f"expected={sorted(expected_batch_keys)}"
        )
    if tuple(
        batch["x"].shape
    ) != (16, 16, 58, 32):
        failures.append(
            f"collated x shape="
            f"{tuple(batch['x'].shape)}"
        )
    if tuple(
        batch[
            "physical_port_mask"
        ].shape
    ) != (16, 16, 10):
        failures.append(
            "collated physical-port-mask "
            "shape mismatch"
        )

    expected_role_mask = (
        batch["y_source"].to(torch.int64)
        + 2
        * batch["y_transit"].to(
            torch.int64
        )
        + 4
        * batch["y_victim"].to(
            torch.int64
        )
    )
    actual_role_mask = batch[
        "role_mask"
    ].to(torch.int64)

    role_mask_mismatch_count = int(
        (
            actual_role_mask
            != expected_role_mask
        ).sum().item()
    )
    if role_mask_mismatch_count != 0:
        failures.append(
            f"tiny batch role_mask bit-field "
            f"mismatches={role_mask_mismatch_count}"
        )

    device = torch.device(
        "cuda"
        if torch.cuda.is_available()
        else "cpu"
    )
    batch = {
        key: value.to(device)
        for key, value in batch.items()
    }

    active_mask = (
        batch["y_attack"] >= 0.5
    )
    if int(
        active_mask.sum().item()
    ) != 8:
        failures.append(
            f"active item count="
            f"{int(active_mask.sum().item())}, "
            "expected 8"
        )

    count_class_mapping = {
        raw_count: class_index
        for class_index, raw_count in enumerate(
            EXPECTED_COUNT_CLASS_VALUES
        )
    }
    count_targets = torch.full(
        batch[
            "y_attacker_count"
        ].shape,
        fill_value=-100,
        dtype=torch.int64,
        device=device,
    )

    for raw_count, class_index in (
        count_class_mapping.items()
    ):
        selector = (
            active_mask
            & (
                batch[
                    "y_attacker_count"
                ]
                == raw_count
            )
        )
        count_targets[selector] = class_index

    if bool(
        (
            count_targets[active_mask]
            < 0
        ).any().item()
    ):
        failures.append(
            "one or more active count targets "
            "were not mapped"
        )

    active_raw_counts = sorted(
        int(value)
        for value in torch.unique(
            batch[
                "y_attacker_count"
            ][active_mask]
        ).tolist()
    )
    if (
        active_raw_counts
        != EXPECTED_COUNT_CLASS_VALUES
    ):
        failures.append(
            f"tiny batch active raw counts="
            f"{active_raw_counts}, expected "
            f"{EXPECTED_COUNT_CLASS_VALUES}"
        )

    model = ModelClass().to(device)
    parameter_count = sum(
        parameter.numel()
        for parameter in model.parameters()
    )
    trainable_parameter_count = sum(
        parameter.numel()
        for parameter in model.parameters()
        if parameter.requires_grad
    )

    if (
        parameter_count
        != EXPECTED_PARAMETER_COUNT
    ):
        failures.append(
            f"model parameter count="
            f"{parameter_count}, expected "
            f"{EXPECTED_PARAMETER_COUNT}"
        )
    if (
        trainable_parameter_count
        != EXPECTED_PARAMETER_COUNT
    ):
        failures.append(
            f"trainable parameter count="
            f"{trainable_parameter_count}, expected "
            f"{EXPECTED_PARAMETER_COUNT}"
        )
    if model.count_head.out_features != 4:
        failures.append(
            "P2 count head does not have 4 logits"
        )
    if list(
        model.count_class_values
    ) != EXPECTED_COUNT_CLASS_VALUES:
        failures.append(
            "model count-class values changed"
        )

    with torch.no_grad():
        shape_outputs = model(
            batch["x"],
            batch["physical_port_mask"],
        )

    expected_output_shapes = {
        "attack_logits": (16,),
        "count_logits": (16, 4),
        "source_logits": (16, 16),
        "transit_logits": (16, 16),
        "victim_logits": (16, 16),
        "path_logits": (16, 16),
    }
    for key, expected_shape in (
        expected_output_shapes.items()
    ):
        if tuple(
            shape_outputs[key].shape
        ) != expected_shape:
            failures.append(
                f"{key} shape="
                f"{tuple(shape_outputs[key].shape)}, "
                f"expected {expected_shape}"
            )

    if failures:
        report = {
            "stage": STAGE,
            "status": "HOLD",
            "failures": failures,
            "warnings": warnings,
            "selection": selected_pairs,
            "training_performed": False,
            "validation_tensor_contents_accessed": False,
            "test_directory_enumerated": False,
            "test_tensor_contents_accessed": False,
        }
        write_json(
            output_dir / f"{STAGE}.json",
            report,
        )
        atomic_write(
            output_dir / f"{STAGE}_HOLD",
            f"{STAGE}_HOLD\n",
        )
        print(f"{STAGE}_HOLD")
        for failure in failures:
            print("FAIL:", failure)
        return 1

    graph_pos_weight = positive_weight(
        batch["y_attack"]
    )
    role_pos_weights = {
        "source": positive_weight(
            batch["y_source"]
        ),
        "transit": positive_weight(
            batch["y_transit"]
        ),
        "victim": positive_weight(
            batch["y_victim"]
        ),
        "path": positive_weight(
            batch["y_attack_path"]
        ),
    }

    optimizer = torch.optim.Adam(
        model.parameters(),
        lr=LEARNING_RATE,
    )

    history: list[dict[str, Any]] = []
    initial_loss = None
    final_loss = None
    final_metrics = None
    completed_step = 0
    stable_exact_steps = 0
    maximum_gradient_norm = 0.0
    maximum_nonzero_gradient_tensors = 0

    def compute_loss(
        outputs: dict[str, torch.Tensor],
    ) -> tuple[
        torch.Tensor,
        dict[str, torch.Tensor],
    ]:
        components = {
            "attack": (
                F.binary_cross_entropy_with_logits(
                    outputs["attack_logits"],
                    batch["y_attack"].float(),
                    pos_weight=graph_pos_weight,
                )
            ),
            "count": (
                F.cross_entropy(
                    outputs[
                        "count_logits"
                    ][active_mask],
                    count_targets[active_mask],
                )
            ),
            "source": (
                F.binary_cross_entropy_with_logits(
                    outputs["source_logits"],
                    batch["y_source"].float(),
                    pos_weight=role_pos_weights[
                        "source"
                    ],
                )
            ),
            "transit": (
                F.binary_cross_entropy_with_logits(
                    outputs["transit_logits"],
                    batch["y_transit"].float(),
                    pos_weight=role_pos_weights[
                        "transit"
                    ],
                )
            ),
            "victim": (
                F.binary_cross_entropy_with_logits(
                    outputs["victim_logits"],
                    batch["y_victim"].float(),
                    pos_weight=role_pos_weights[
                        "victim"
                    ],
                )
            ),
            "path": (
                F.binary_cross_entropy_with_logits(
                    outputs["path_logits"],
                    batch[
                        "y_attack_path"
                    ].float(),
                    pos_weight=role_pos_weights[
                        "path"
                    ],
                )
            ),
        }

        total = sum(
            LOSS_WEIGHTS[key]
            * value
            for key, value in components.items()
        )
        return total, components

    for step in range(
        1,
        MAX_STEPS + 1,
    ):
        model.train()
        optimizer.zero_grad(
            set_to_none=True
        )

        outputs = model(
            batch["x"],
            batch["physical_port_mask"],
        )
        loss, components = compute_loss(
            outputs
        )

        if not torch.isfinite(loss):
            failures.append(
                f"non-finite loss at step {step}"
            )
            break

        if initial_loss is None:
            initial_loss = float(
                loss.item()
            )

        loss.backward()

        squared_norm = 0.0
        nonzero_gradient_tensors = 0
        for parameter in model.parameters():
            if parameter.grad is None:
                continue

            gradient = parameter.grad.detach()
            squared_norm += float(
                gradient.float()
                .pow(2)
                .sum()
                .item()
            )
            if bool(
                (gradient != 0).any().item()
            ):
                nonzero_gradient_tensors += 1

        gradient_norm = math.sqrt(
            squared_norm
        )
        maximum_gradient_norm = max(
            maximum_gradient_norm,
            gradient_norm,
        )
        maximum_nonzero_gradient_tensors = max(
            maximum_nonzero_gradient_tensors,
            nonzero_gradient_tensors,
        )

        optimizer.step()

        model.eval()
        with torch.no_grad():
            current_outputs = model(
                batch["x"],
                batch[
                    "physical_port_mask"
                ],
            )
            current_loss, current_components = (
                compute_loss(current_outputs)
            )
            metrics = evaluate(
                current_outputs,
                batch,
                count_targets,
                active_mask,
            )

        completed_step = step
        final_loss = float(
            current_loss.item()
        )
        final_metrics = metrics

        if (
            metrics[
                "all_tasks_all_exact"
            ]
            and final_loss <= 0.05
        ):
            stable_exact_steps += 1
        else:
            stable_exact_steps = 0

        if (
            step == 1
            or step % 25 == 0
            or stable_exact_steps > 0
        ):
            history.append(
                {
                    "step": step,
                    "loss": final_loss,
                    "attack_loss": float(
                        current_components[
                            "attack"
                        ].item()
                    ),
                    "count_loss": float(
                        current_components[
                            "count"
                        ].item()
                    ),
                    "source_loss": float(
                        current_components[
                            "source"
                        ].item()
                    ),
                    "transit_loss": float(
                        current_components[
                            "transit"
                        ].item()
                    ),
                    "victim_loss": float(
                        current_components[
                            "victim"
                        ].item()
                    ),
                    "path_loss": float(
                        current_components[
                            "path"
                        ].item()
                    ),
                    "gradient_norm_before_step": (
                        gradient_norm
                    ),
                    "graph_all_exact": (
                        metrics[
                            "graph"
                        ][
                            "all_exact"
                        ]
                    ),
                    "count_all_exact": (
