    baseline_rows: list[dict[str, Any]] = []
    baseline_details: dict[str, Any] = {}

    def record_graph_baseline(
        name: str,
        prediction: np.ndarray,
        family: str,
        learned_input_status: str,
        details: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        metrics = confusion_metrics(
            validation["graph"],
            prediction,
        )
        row = {
            "task": "graph",
            "baseline": name,
            "family": family,
            "learned_input_status": learned_input_status,
            **metrics,
        }
        baseline_rows.append(row)
        baseline_details[name] = {
            "metrics": metrics,
            "details": details or {},
        }
        return metrics

    always_normal = record_graph_baseline(
        "always_normal",
        np.zeros_like(validation["graph"]),
        "trivial",
        "none",
    )
    always_attack = record_graph_baseline(
        "always_attack",
        np.ones_like(validation["graph"]),
        "trivial",
        "none",
    )

    train_majority_label = int(
        train["graph"].mean() >= 0.5
    )
    train_majority = record_graph_baseline(
        "train_majority_graph",
        np.full_like(
            validation["graph"],
            train_majority_label,
        ),
        "trivial",
        "none",
        {"train_majority_label": train_majority_label},
    )

    mode_only = record_graph_baseline(
        "quarantined_mode_only",
        validation["mode"],
        "provenance_shortcut",
        "forbidden",
    )

    def threshold_graph_baseline(
        name: str,
        train_values: np.ndarray,
        validation_values: np.ndarray,
        family: str,
        learned_input_status: str,
    ) -> dict[str, Any]:
        fit = fit_threshold(
            train_values,
            train["graph"],
        )
        prediction = apply_threshold(
            validation_values,
            fit["threshold"],
            fit["direction"],
        )
        return record_graph_baseline(
            name,
            prediction,
            family,
            learned_input_status,
            {
                "threshold": fit["threshold"],
                "direction": fit["direction"],
                "train_metrics": fit["train_metrics"],
            },
        )

    epoch_position = threshold_graph_baseline(
        "forbidden_epoch_position_only",
        train["progress"],
        validation["progress"],
        "timing_shortcut",
        "forbidden",
    )
    common_length = threshold_graph_baseline(
        "forbidden_common_length_only",
        train["common_length"],
        validation["common_length"],
        "length_shortcut",
        "forbidden",
    )

    status_max_fit = fit_threshold(
        train["status_max"],
        train["graph"],
    )
    status_mean_fit = fit_threshold(
        train["status_mean"],
        train["graph"],
    )
    status_candidates = [
        ("max", status_max_fit),
        ("mean", status_mean_fit),
    ]
    status_summary_name, status_fit = max(
        status_candidates,
        key=lambda item: (
            item[1]["train_metrics"]["balanced_accuracy"],
            item[1]["train_metrics"]["f1"],
        ),
    )
    status_values = validation[
        "status_max" if status_summary_name == "max"
        else "status_mean"
    ]
    status_prediction = apply_threshold(
        status_values,
        status_fit["threshold"],
        status_fit["direction"],
    )
    status_only = record_graph_baseline(
        "quarantined_status_flags_only",
        status_prediction,
        "instrumentation_shortcut",
        "forbidden_and_excluded",
        {
            "summary": status_summary_name,
            "threshold": status_fit["threshold"],
            "direction": status_fit["direction"],
            "train_metrics": status_fit["train_metrics"],
        },
    )

    # ------------------------------------------------------------------
    # Count baselines, active windows only
    # ------------------------------------------------------------------
    train_active_counts = train["count"][train_active]
    validation_active_counts = validation["count"][
        validation_active
    ]
    count_values, count_frequencies = np.unique(
        train_active_counts,
        return_counts=True,
    )
    most_common_count = int(
        count_values[np.argmax(count_frequencies)]
    )
    count_prediction = np.full_like(
        validation_active_counts,
        most_common_count,
    )
    most_common_count_accuracy = float(
        (count_prediction == validation_active_counts).mean()
    )
    baseline_rows.append(
        {
            "task": "count_active",
            "baseline": "most_common_active_count",
            "family": "trivial",
            "learned_input_status": "none",
            "accuracy": most_common_count_accuracy,
            "predicted_count": most_common_count,
            "support": int(validation_active_counts.size),
        }
    )
    baseline_details["most_common_active_count"] = {
        "predicted_count": most_common_count,
        "validation_accuracy": most_common_count_accuracy,
    }

    category_count_accuracy = float(
        (
            validation["category"][validation_active]
            == validation_active_counts
        ).mean()
    )
    baseline_rows.append(
        {
            "task": "count_active",
            "baseline": "quarantined_category_only_count",
            "family": "provenance_shortcut",
            "learned_input_status": "forbidden",
            "accuracy": category_count_accuracy,
            "support": int(validation_active_counts.size),
        }
    )
    baseline_details["quarantined_category_only_count"] = {
        "validation_accuracy": category_count_accuracy,
    }

    # ------------------------------------------------------------------
    # Source trivial and traffic baselines, active windows only
    # ------------------------------------------------------------------
    train_active_source = train["source"][train_active]
    validation_active_source = validation["source"][
        validation_active
    ]

    train_source_frequency = train_active_source.sum(axis=0)
    most_common_source_node = int(
        np.argmax(train_source_frequency)
    )
    most_common_source_prediction = np.full(
        validation_active_source.shape[0],
        most_common_source_node,
        dtype=np.int64,
    )
    most_common_source_metrics = source_single_prediction_metrics(
        validation_active_source,
        most_common_source_prediction,
    )
    baseline_rows.append(
        {
            "task": "source_active",
            "baseline": "most_common_source_router",
            "family": "trivial_spatial_prior",
            "learned_input_status": (
                "router_identity_forbidden; audit_only"
            ),
            **most_common_source_metrics,
            "predicted_router": most_common_source_node,
        }
    )
    baseline_details["most_common_source_router"] = {
        "predicted_router": most_common_source_node,
        "train_source_frequency": (
            train_source_frequency.astype(int).tolist()
        ),
        "validation_metrics": most_common_source_metrics,
    }

    traffic_source_prediction = validation["traffic_router"][
        validation_active
    ]
    traffic_source_metrics = source_single_prediction_metrics(
        validation_active_source,
        traffic_source_prediction,
    )
    baseline_rows.append(
        {
            "task": "source_active",
            "baseline": "highest_final_epoch_traffic_router",
            "family": "observable_trivial_heuristic",
            "learned_input_status": "allowed_PRIMARY58",
            **traffic_source_metrics,
        }
    )
    baseline_details["highest_final_epoch_traffic_router"] = {
        "traffic_definition": (
            "argmax_router sum(final_epoch standardized "
            "in/out count channels 0..9)"
        ),
        "validation_metrics": traffic_source_metrics,
    }

    # ------------------------------------------------------------------
    # Physical-mask-only role priors, active windows only
    # ------------------------------------------------------------------
    signatures = mask_signature(physical_mask)
    mask_role_baselines: dict[str, Any] = {}

    for role in ("source", "transit", "victim", "path"):
        result = role_mask_prior_baseline(
            train[role][train_active],
            validation[role][validation_active],
            signatures,
        )
        mask_role_baselines[role] = result
        baseline_rows.append(
            {
                "task": f"{role}_active_node",
                "baseline": "physical_mask_only_role_prior",
                "family": "structural_shortcut",
                "learned_input_status": "allowed_topology_mask",
                "balanced_accuracy": (
                    result["validation_metrics"][
                        "balanced_accuracy"
                    ]
                ),
                "f1": result["validation_metrics"]["f1"],
                "precision": (
                    result["validation_metrics"]["precision"]
                ),
                "recall": result["validation_metrics"]["recall"],
                "fpr": result["validation_metrics"]["fpr"],
                "auroc": result["validation_auroc"],
                "average_precision": (
                    result["validation_average_precision"]
                ),
                "threshold": result["threshold"],
                "direction": result["direction"],
            }
        )

    baseline_details["physical_mask_only_role_priors"] = (
        mask_role_baselines
    )

    # ------------------------------------------------------------------
    # Shortcut interpretation
    # ------------------------------------------------------------------
    epoch_ba = epoch_position["balanced_accuracy"]
    if epoch_ba >= EPOCH_POSITION_BLOCK_BA:
        shortcut_blocks.append(
            "epoch-position-only graph balanced accuracy "
            f"{epoch_ba:.4f} >= {EPOCH_POSITION_BLOCK_BA:.2f}"
        )
    elif epoch_ba >= EPOCH_POSITION_WARN_BA:
        shortcut_warnings.append(
            "epoch-position-only graph balanced accuracy "
            f"{epoch_ba:.4f} >= {EPOCH_POSITION_WARN_BA:.2f}"
        )

    for role, result in mask_role_baselines.items():
        auc = result["validation_auroc"]
        if auc is None:
            continue
        if auc >= MASK_ROLE_BLOCK_AUROC:
            shortcut_blocks.append(
                f"physical-mask-only {role} AUROC "
                f"{auc:.4f} >= {MASK_ROLE_BLOCK_AUROC:.2f}"
            )
        elif auc >= MASK_ROLE_WARN_AUROC:
            shortcut_warnings.append(
                f"physical-mask-only {role} AUROC "
                f"{auc:.4f} >= {MASK_ROLE_WARN_AUROC:.2f}"
            )

    if (
        most_common_source_metrics["hit_at_1"]
        >= COMMON_SOURCE_WARN_HIT1
    ):
        shortcut_warnings.append(
            "most-common-source hit@1 "
            f"{most_common_source_metrics['hit_at_1']:.4f} >= "
            f"{COMMON_SOURCE_WARN_HIT1:.2f}"
        )

    if (
        traffic_source_metrics["hit_at_1"]
        >= TRAFFIC_SOURCE_WARN_HIT1
    ):
        shortcut_warnings.append(
            "highest-traffic-router source hit@1 "
            f"{traffic_source_metrics['hit_at_1']:.4f} >= "
            f"{TRAFFIC_SOURCE_WARN_HIT1:.2f}; treat as a required "
            "paper baseline, not leakage"
        )

    # Expected forbidden baselines are diagnostic only.
    diagnostic_notes = [
        (
            "Mode, category, status flags, run length, and epoch position "
            "remain forbidden learned inputs regardless of their scores."
        ),
        (
            "A strong highest-traffic-router result is an observable "
            "heuristic baseline and must be reported against the model."
        ),
        (
            "Physical mask is an authorized B3 input, so strong mask-only "
            "role AUROC indicates dataset spatial bias and is a blocker "
            "at the configured threshold."
        ),
        (
            "role_mask is the audited bit-field source + 2*transit + "
            "4*victim. It is bookkeeping only and is neither a model "
            "input nor an independently trained output."
        ),
        (
            "The P2 B3 architecture uses four active-count logits for "
            "raw attacker counts 1,2,3,4. Zero count remains represented "
            "by the graph normal/attack head."
        ),
    ]

    status = (
        "HOLD"
        if shortcut_blocks
        else "COMPLETE"
    )
    decision = (
        "BLOCK_P2_B1_FOR_SHORTCUT_REMEDIATION"
        if shortcut_blocks
        else "AUTHORIZE_P2_B1_TRAINING_PROTOCOL_LOCK"
    )
    next_stage = (
        None
        if shortcut_blocks
        else "V5_P2_B1_TRAINING_PROTOCOL_LOCK"
    )

    pair_csv_path = (
        output_dir
        / "V5_P2_B0_R3_PAIR_LABEL_AUDIT.csv"
    )
    baseline_csv_path = (
        output_dir
        / "V5_P2_B0_R3_TRIVIAL_AND_SHORTCUT_BASELINES.csv"
    )
    label_summary_path = (
        output_dir
        / "V5_P2_B0_R3_LABEL_SUMMARY.json"
    )

    write_csv(pair_csv_path, pair_audit_rows)
    write_csv(baseline_csv_path, baseline_rows)
    write_json(
        label_summary_path,
        {
            "splits": label_summaries,
            "label_violation_counts": dict(
                label_violation_counts
            ),
            "label_relation_diagnostics": {
                key: {
                    "matching_items": int(value),
                    "total_items": int(
                        relation_counts["total_items"]
                    ),
                    "fraction": (
                        value
                        / max(
                            1,
                            relation_counts["total_items"],
                        )
                    ),
                }
                for key, value in relation_counts.items()
                if key != "total_items"
            },
        },
    )

    report = {
        "stage": STAGE,
        "status": status,
        "decision": decision,
        "dataset": {
            "link_path": str(root_input.absolute()),
            "resolved_root": str(root),
        },
        "coverage": {
            "train_pairs": int(processed_pairs["train"]),
            "validation_pairs": int(
                processed_pairs["validation"]
            ),
            "total_pairs": int(sum(processed_pairs.values())),
            "train_runs": int(processed_runs["train"]),
            "validation_runs": int(
                processed_runs["validation"]
            ),
            "total_runs": int(sum(processed_runs.values())),
            "train_aligned_items": int(
                processed_windows["train"]
            ),
            "validation_aligned_items": int(
                processed_windows["validation"]
            ),
            "total_aligned_items": int(
                sum(processed_windows.values())
            ),
        },
        "corrected_contracts": {
            "count_categories": [1, 2, 3, 4],
            "active_count_values": [1, 2, 3, 4],
            "count_head_logits": 4,
            "corrected_model_parameter_count": 43273,
            "role_mask_semantics": (
                "source + 2*transit + 4*victim"
            ),
            "role_mask_learned_input": False,
            "role_mask_independent_model_output": False,
        },
        "label_integrity": {
            "violation_counts": dict(label_violation_counts),
            "all_zero": not any(label_violation_counts.values()),
            "relation_diagnostics": {
                key: {
                    "matching_items": int(value),
                    "total_items": int(
                        relation_counts["total_items"]
                    ),
                    "fraction": (
                        value
                        / max(
                            1,
                            relation_counts["total_items"],
                        )
                    ),
                }
                for key, value in relation_counts.items()
                if key != "total_items"
            },
        },
        "label_summaries": label_summaries,
        "baselines": baseline_details,
        "shortcut_policy": {
            "epoch_position_block_balanced_accuracy": (
                EPOCH_POSITION_BLOCK_BA
            ),
            "epoch_position_warning_balanced_accuracy": (
                EPOCH_POSITION_WARN_BA
            ),
            "mask_role_block_auroc": MASK_ROLE_BLOCK_AUROC,
            "mask_role_warning_auroc": MASK_ROLE_WARN_AUROC,
            "common_source_warning_hit_at_1": (
                COMMON_SOURCE_WARN_HIT1
            ),
            "traffic_source_warning_hit_at_1": (
                TRAFFIC_SOURCE_WARN_HIT1
            ),
        },
        "shortcut_blocks": shortcut_blocks,
        "shortcut_warnings": shortcut_warnings,
        "diagnostic_notes": diagnostic_notes,
        "artifacts": {
            "pair_label_audit_csv": [
                str(pair_csv_path),
                sha256_file(pair_csv_path),
            ],
            "baseline_csv": [
                str(baseline_csv_path),
                sha256_file(baseline_csv_path),
            ],
            "label_summary_json": [
                str(label_summary_path),
                sha256_file(label_summary_path),
            ],
        },
        "provenance": {
            "a0_report_sha256": sha256_file(paths["a0_report"]),
            "a0_lock_sha256": sha256_file(paths["a0_lock"]),
            "a1_r2_report_sha256": sha256_file(
                paths["a1_r2_report"]
            ),
            "a1_r2_lock_sha256": sha256_file(
                paths["a1_r2_lock"]
            ),
            "pair_manifest_sha256": sha256_file(
                paths["pair_manifest"]
            ),
            "a2_r2_report_sha256": sha256_file(
                paths["a2_r2_report"]
            ),
            "a2_r2_lock_sha256": sha256_file(
                paths["a2_r2_lock"]
            ),
            "a2_r2_mask_sha256": sha256_file(
                paths["a2_r2_mask"]
            ),
            "a3_report_sha256": sha256_file(
                paths["a3_report"]
            ),
            "a3_lock_sha256": sha256_file(paths["a3_lock"]),
            "b0_r1b_report_sha256": sha256_file(
                paths["b0_r1b_report"]
            ),
            "b0_r1b_lock_sha256": sha256_file(
                paths["b0_r1b_lock"]
            ),
            "b0_r2_report_sha256": sha256_file(
                paths["b0_r2_report"]
            ),
            "b0_r2_lock_sha256": sha256_file(
                paths["b0_r2_lock"]
            ),
            "loader_sha256": sha256_file(paths["loader"]),
            "corrected_model_sha256": sha256_file(paths["model"]),
        },
        "security_boundary": {
            "train_tensor_contents_accessed": True,
            "validation_tensor_contents_accessed": True,
            "test_directory_existence_checked": False,
            "test_directory_enumerated": False,
            "test_tensor_files_opened": False,
            "test_tensor_bytes_read": False,
            "test_tensor_contents_accessed": False,
            "test_dataset_constructed": False,
            "test_windows_constructed": False,
            "test_labels_read": False,
        },
        "failures": failures,
        "warnings": warnings + shortcut_warnings,
        "next_stage": next_stage,
    }

    report_path = output_dir / f"{STAGE}.json"
    write_json(report_path, report)

    if status == "HOLD":
        atomic_write(
            output_dir / f"{STAGE}_HOLD",
            f"{STAGE}_HOLD\n",
        )
        print("===== V5 P2-B0-R3 FINAL =====")
        print("status: HOLD")
        print("decision:", decision)
        print("label_integrity_pass: true")
        print("shortcut_block_count:", len(shortcut_blocks))
        for item in shortcut_blocks:
            print("SHORTCUT_BLOCK:", item)
        print("shortcut_warning_count:", len(shortcut_warnings))
        for item in shortcut_warnings:
            print("SHORTCUT_WARNING:", item)
        print("test_directory_enumerated: false")
        print("test_tensor_contents_accessed: false")
        print(f"{STAGE}_HOLD")
        return 1

    lock = {
        "status": COMPLETE,
        "decision": decision,
        "report_sha256": sha256_file(report_path),
        "pair_label_audit_sha256": sha256_file(pair_csv_path),
        "baseline_csv_sha256": sha256_file(baseline_csv_path),
        "label_summary_sha256": sha256_file(label_summary_path),
        "total_pairs": int(sum(processed_pairs.values())),
        "total_runs": int(sum(processed_runs.values())),
        "total_aligned_items": int(sum(processed_windows.values())),
        "label_integrity_pass": True,
        "label_violation_counts": dict(label_violation_counts),
        "count_categories": [1, 2, 3, 4],
        "active_count_values": [1, 2, 3, 4],
        "count_head_logits": 4,
        "corrected_model_parameter_count": 43273,
        "corrected_model_sha256": sha256_file(paths["model"]),
        "role_mask_semantics": (
            "bitfield3_source1_transit2_victim4"
        ),
        "shortcut_block_count": 0,
        "shortcut_warning_count": len(shortcut_warnings),
        "epoch_position_validation_balanced_accuracy": (
            epoch_position["balanced_accuracy"]
        ),
        "mask_role_validation_auroc": {
            role: result["validation_auroc"]
            for role, result in mask_role_baselines.items()
        },
        "most_common_source_validation_hit_at_1": (
            most_common_source_metrics["hit_at_1"]
        ),
        "highest_traffic_source_validation_hit_at_1": (
            traffic_source_metrics["hit_at_1"]
        ),
        "test_directory_enumerated": False,
        "test_tensor_contents_accessed": False,
        "next_stage": next_stage,
        "script_sha256": sha256_file(Path(__file__)),
    }
    write_json(output_dir / f"{STAGE}_LOCK.json", lock)
    atomic_write(output_dir / COMPLETE, COMPLETE + "\n")

    print("===== V5 P2-B0-R3 FINAL =====")
    print("status: COMPLETE")
    print("decision:", decision)
    print("train_pairs:", processed_pairs["train"])
    print("validation_pairs:", processed_pairs["validation"])
    print("total_pairs:", sum(processed_pairs.values()))
    print("total_runs:", sum(processed_runs.values()))
    print("train_aligned_items:", processed_windows["train"])
    print(
        "validation_aligned_items:",
        processed_windows["validation"],
    )
    print("total_aligned_items:", sum(processed_windows.values()))
    print("label_integrity_pass: true")
    print("label_violation_count: 0")
    print("count_categories: [1, 2, 3, 4]")
    print("active_count_values: [1, 2, 3, 4]")
    print("count_head_logits: 4")
    print("corrected_model_parameter_count: 43273")
    print(
        "role_mask_semantics: "
        "bitfield3_source1_transit2_victim4"
    )
    print(
        "graph_validation_prevalence:",
        f"{label_summaries['validation']['graph_positive_prevalence']:.10g}",
    )
    print(
        "always_normal_validation_balanced_accuracy:",
        f"{always_normal['balanced_accuracy']:.10g}",
    )
    print(
        "epoch_position_validation_balanced_accuracy:",
        f"{epoch_position['balanced_accuracy']:.10g}",
    )
    print(
        "common_length_validation_balanced_accuracy:",
        f"{common_length['balanced_accuracy']:.10g}",
    )
    print(
        "quarantined_status_validation_balanced_accuracy:",
        f"{status_only['balanced_accuracy']:.10g}",
    )
    print(
        "quarantined_mode_validation_balanced_accuracy:",
        f"{mode_only['balanced_accuracy']:.10g}",
    )
    print(
        "most_common_count_validation_accuracy:",
        f"{most_common_count_accuracy:.10g}",
    )
    print(
        "quarantined_category_count_validation_accuracy:",
        f"{category_count_accuracy:.10g}",
    )
    print(
        "most_common_source_validation_hit_at_1:",
        f"{most_common_source_metrics['hit_at_1']:.10g}",
    )
    print(
        "highest_traffic_source_validation_hit_at_1:",
        f"{traffic_source_metrics['hit_at_1']:.10g}",
    )
    for role in ("source", "transit", "victim", "path"):
        print(
            f"mask_only_{role}_validation_auroc:",
            mask_role_baselines[role]["validation_auroc"],
        )
    print("shortcut_block_count: 0")
    print("shortcut_warning_count:", len(shortcut_warnings))
    for item in shortcut_warnings:
        print("SHORTCUT_WARNING:", item)
    print("test_directory_enumerated: false")
    print("test_tensor_contents_accessed: false")
    print("failure_count:", len(failures))
    print(
        "warning_count:",
        len(warnings) + len(shortcut_warnings),
    )
    print("next_stage:", next_stage)
    print(COMPLETE)
    return 0

def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", type=Path, required=True)
    parser.add_argument("--a0-dir", type=Path, required=True)
    parser.add_argument("--a1-r2-dir", type=Path, required=True)
    parser.add_argument("--a2-r2-dir", type=Path, required=True)
    parser.add_argument("--a3-dir", type=Path, required=True)
    parser.add_argument("--a4-dir", type=Path, required=True)
    parser.add_argument("--loader-path", type=Path, required=True)
    parser.add_argument("--output-dir", type=Path, required=True)
    args = parser.parse_args()

    root_input = args.root.expanduser()
    root = root_input.resolve()
    a0_dir = args.a0_dir.expanduser().resolve()
    a1_r2_dir = args.a1_r2_dir.expanduser().resolve()
    a2_r2_dir = args.a2_r2_dir.expanduser().resolve()
    a3_dir = args.a3_dir.expanduser().resolve()
    a4_dir = args.a4_dir.expanduser().resolve()
    loader_path = args.loader_path.expanduser().resolve()
    output_dir = args.output_dir.expanduser().resolve()

    if output_dir.exists():
        print(
            f"STOP: output already exists: {output_dir}",
            file=sys.stderr,
        )
        return 2
    output_dir.mkdir(parents=True)

    failures: list[str] = []
    warnings: list[str] = []
    shortcut_blocks: list[str] = []
    shortcut_warnings: list[str] = []

    paths = {
        "a0_report": (
            a0_dir
            / "V5_P2_A0_INDEPENDENT_DATASET_METADATA_AUDIT.json"
        ),
        "a0_lock": (
            a0_dir
            / "V5_P2_A0_INDEPENDENT_DATASET_METADATA_AUDIT_LOCK.json"
        ),
        "a1_r2_report": (
            a1_r2_dir
            / "V5_P2_A1_R2_PAIR_ALIGNED_WINDOW_CONTRACT.json"
        ),
        "a1_r2_lock": (
            a1_r2_dir
            / "V5_P2_A1_R2_PAIR_ALIGNED_WINDOW_CONTRACT_LOCK.json"
        ),
        "pair_manifest": (
            a1_r2_dir
            / "V5_P2_A1_R2_PAIR_ALIGNED_WINDOW_MANIFEST.csv"
        ),
        "a2_r2_report": (
            a2_r2_dir
            / "V5_P2_A2_R2_FEATURE_NORMALIZATION_AND_MASK_CONTRACT.json"
        ),
        "a2_r2_lock": (
            a2_r2_dir
            / "V5_P2_A2_R2_FEATURE_NORMALIZATION_AND_MASK_CONTRACT_LOCK.json"
        ),
        "a2_r2_mask": (
            a2_r2_dir
            / "V5_P2_A2_R2_TOPOLOGY_DERIVED_BOOLEAN_PORT_MASK.pt"
        ),
        "a3_report": (
            a3_dir
            / "V5_P2_A3_PAIR_ALIGNED_PRIMARY58_LOADER_CONTRACT.json"
        ),
        "a3_lock": (
            a3_dir
            / "V5_P2_A3_PAIR_ALIGNED_PRIMARY58_LOADER_CONTRACT_LOCK.json"
        ),
        "a4_report": (
            a4_dir
            / "V5_P2_A4_LOADER_INTEGRATION_AND_TINY_OVERFIT.json"
        ),
        "a4_lock": (
            a4_dir
            / "V5_P2_A4_LOADER_INTEGRATION_AND_TINY_OVERFIT_LOCK.json"
        ),
        "loader": loader_path,
    }

    for name, path in paths.items():
        if not path.is_file():
            failures.append(f"missing prerequisite {name}: {path}")

    for split in ("train", "validation"):
        if not (root / "runs" / split).is_dir():
            failures.append(f"missing runs/{split}")

    if failures:
        report = {
            "stage": STAGE,
            "status": "HOLD",
            "failures": failures,
            "warnings": warnings,
            "test_directory_enumerated": False,
            "test_tensor_contents_accessed": False,
        }
        write_json(output_dir / f"{STAGE}.json", report)
        atomic_write(
            output_dir / f"{STAGE}_HOLD",
            f"{STAGE}_HOLD\n",
        )
        print(f"{STAGE}_HOLD")
        return 1

    reports = {
        "A0": load_json(paths["a0_report"]),
        "A1-R2": load_json(paths["a1_r2_report"]),
        "A2-R2": load_json(paths["a2_r2_report"]),
        "A3": load_json(paths["a3_report"]),
        "A4": load_json(paths["a4_report"]),
    }
    locks = {
        "A0": load_json(paths["a0_lock"]),
        "A1-R2": load_json(paths["a1_r2_lock"]),
        "A2-R2": load_json(paths["a2_r2_lock"]),
        "A3": load_json(paths["a3_lock"]),
        "A4": load_json(paths["a4_lock"]),
    }

    report_paths = {
        "A0": paths["a0_report"],
        "A1-R2": paths["a1_r2_report"],
        "A2-R2": paths["a2_r2_report"],
        "A3": paths["a3_report"],
        "A4": paths["a4_report"],
    }

    for label in reports:
        if reports[label].get("status") != "COMPLETE":
            failures.append(f"{label} status is not COMPLETE")
        if (
            locks[label].get("report_sha256")
            != sha256_file(report_paths[label])
        ):
            failures.append(f"{label} report SHA mismatch")
        if reports[label].get("security_boundary", {}).get(
            "test_tensor_contents_accessed"
        ) is not False:
            failures.append(
                f"{label} does not certify untouched test tensors"
            )

    if locks["A1-R2"].get("aligned_windows") != 82694:
        failures.append("A1-R2 aligned-window count changed")
    if locks["A1-R2"].get("pair_count") != 489:
        failures.append("A1-R2 pair count changed")
    if (
        locks["A1-R2"].get("pair_manifest_sha256")
        != sha256_file(paths["pair_manifest"])
    ):
        failures.append("A1-R2 pair manifest SHA mismatch")
    if (
        locks["A2-R2"].get("corrected_port_mask_sha256")
        != sha256_file(paths["a2_r2_mask"])
    ):
        failures.append("A2-R2 port-mask SHA mismatch")
    if locks["A2-R2"].get("primary58_indices") != PRIMARY58_INDICES:
        failures.append("A2-R2 PRIMARY58 indices changed")
    if locks["A2-R2"].get(
        "second_normalization_forbidden"
    ) is not True:
        failures.append("second-normalization contract changed")
    if locks["A3"].get("loader_sha256") != sha256_file(paths["loader"]):
        failures.append("A3 loader SHA mismatch")
    if set(locks["A3"].get("item_keys", [])) != EXPECTED_ITEM_KEYS:
        failures.append("A3 loader item-key contract changed")
    if locks["A4"].get("all_tasks_all_exact") is not True:
        failures.append("A4 did not lock exact tiny overfit")
    if locks["A4"].get("audit_weights_saved") is not False:
        failures.append("A4 unexpectedly saved audit weights")

    if failures:
        report = {
            "stage": STAGE,
            "status": "HOLD",
            "failures": failures,
            "warnings": warnings,
            "test_directory_enumerated": False,
            "test_tensor_contents_accessed": False,
        }
        write_json(output_dir / f"{STAGE}.json", report)
        atomic_write(
            output_dir / f"{STAGE}_HOLD",
            f"{STAGE}_HOLD\n",
        )
        print(f"{STAGE}_HOLD")
        for failure in failures:
            print("FAIL:", failure)
        return 1

    manifest_rows = load_csv(paths["pair_manifest"])
    mask_payload = torch.load(
        paths["a2_r2_mask"],
        map_location="cpu",
        weights_only=False,
    )
    physical_mask = mask_payload.get("mask")
    if (
        not isinstance(physical_mask, torch.Tensor)
        or physical_mask.dtype != torch.bool
        or tuple(physical_mask.shape) != (16, 10)
    ):
        failures.append("A2-R2 physical mask payload is invalid")

    split_data: dict[str, dict[str, list[np.ndarray]]] = {
        split: defaultdict(list)
        for split in ("train", "validation")
    }
    pair_audit_rows: list[dict[str, Any]] = []

    label_violation_counts = Counter()
    relation_counts = Counter()
    processed_pairs = Counter()
    processed_runs = Counter()
    processed_windows = Counter()

    print("===== V5 P2-B0 COMPLETE NON-TEST LABEL AUDIT =====")
    print("test_directory_enumerated: false")
    print("test_tensor_contents_accessed: false")

    rows_by_split = {
        split: [
            row
            for row in manifest_rows
            if row.get("split") == split
        ]
        for split in ("train", "validation")
    }

    for split in ("train", "validation"):
        rows = rows_by_split[split]

        for row_index, row in enumerate(rows, start=1):
            pair_key = row.get("pair_key", "")
            common_length = as_int(row, "common_length")
            window_count = as_int(
                row,
                "window_count_per_member",
            )
            attack_length = as_int(row, "attack_length")
            control_length = as_int(row, "control_length")
            expected_category_count = category_count(pair_key)

            if expected_category_count not in {1, 2, 4}:
                failures.append(
                    f"{split}/{pair_key}: cannot infer K1/K2/K4"
                )
                continue

            target_indices = torch.arange(
                WINDOW - 1,
                common_length,
                STRIDE,
                dtype=torch.int64,
            )
            if int(target_indices.numel()) != window_count:
                failures.append(
                    f"{split}/{pair_key}: target count="
                    f"{int(target_indices.numel())}, "
                    f"manifest={window_count}"
                )
                continue

            pair_member_window_counts = {}
            pair_graph_positive = {}
            pair_inactive_attack_windows = 0
            pair_active_attack_windows = 0

            for mode in ("attack", "control"):
                suffix = mode.upper()
                path = (
                    root
                    / "runs"
                    / split
                    / f"{pair_key}_{suffix}.pt"
                )
                if not path.is_file():
                    failures.append(
                        f"missing {split}/{path.name}"
                    )
                    continue

                payload = torch.load(
                    path,
                    map_location="cpu",
                    weights_only=False,
                )
                processed_runs[split] += 1

                if not isinstance(payload, dict):
                    failures.append(
                        f"{split}/{path.name}: payload is not dict"
                    )
                    continue

                x = payload.get("x")
                if (
                    not isinstance(x, torch.Tensor)
                    or x.dtype != torch.float32
                    or x.ndim != 3
                    or tuple(x.shape[1:]) != (16, 81)
                    or not bool(torch.isfinite(x).all().item())
                ):
                    failures.append(
                        f"{split}/{path.name}: invalid x"
                    )
                    continue

                expected_native_length = (
                    attack_length if mode == "attack"
                    else control_length
                )
                if int(x.shape[0]) != expected_native_length:
                    failures.append(
                        f"{split}/{path.name}: native length="
                        f"{int(x.shape[0])}, manifest="
                        f"{expected_native_length}"
                    )

                logical = {
                    "graph": payload["y_attack"][target_indices],
                    "count": payload[
                        "y_attacker_count"
                    ][target_indices],
                    "source": payload["y_source"][target_indices],
                    "transit": payload["y_transit"][target_indices],
                    "victim": payload["y_victim"][target_indices],
                    "path": payload[
                        "y_attack_path"
                    ][target_indices],
                    "role_mask": payload[
                        "role_mask"
                    ][target_indices],
                }

                expected_shapes = {
                    "graph": (window_count,),
                    "count": (window_count,),
                    "source": (window_count, 16),
                    "transit": (window_count, 16),
                    "victim": (window_count, 16),
                    "path": (window_count, 16),
                    "role_mask": (window_count, 16),
                }
                for key, expected_shape in expected_shapes.items():
                    if tuple(logical[key].shape) != expected_shape:
                        failures.append(
                            f"{split}/{path.name}: {key} shape="
                            f"{tuple(logical[key].shape)}, "
                            f"expected {expected_shape}"
                        )

                for key in (
                    "graph",
                    "source",
                    "transit",
                    "victim",
                    "path",
                    "role_mask",
                ):
                    if not is_binary_tensor(logical[key]):
                        label_violation_counts[
                            f"nonbinary_{key}"
                        ] += 1

                graph = logical["graph"].to(torch.int64)
                count = logical["count"].to(torch.int64)
                source = logical["source"].to(torch.int64)
                transit = logical["transit"].to(torch.int64)
                victim = logical["victim"].to(torch.int64)
                path_label = logical["path"].to(torch.int64)
                role_mask = logical["role_mask"].to(torch.int64)

                allowed_counts = torch.tensor(
                    [0, 1, 2, 4],
                    dtype=torch.int64,
                )
                valid_count = (
                    count.unsqueeze(-1) == allowed_counts
                ).any(dim=-1)
                label_violation_counts[
                    "invalid_count_value"
                ] += int((~valid_count).sum().item())

                active = graph == 1
                inactive = ~active

                label_violation_counts[
                    "graph_count_disagreement"
                ] += int(
                    (
                        active
                        != (count > 0)
                    ).sum().item()
                )
                label_violation_counts[
                    "graph_source_disagreement"
                ] += int(
                    (
                        active
                        != (source.sum(dim=1) > 0)
                    ).sum().item()
                )

                inactive_role_sum = (
                    source[inactive].sum()
                    + transit[inactive].sum()
                    + victim[inactive].sum()
                    + path_label[inactive].sum()
                    + role_mask[inactive].sum()
                )
                label_violation_counts[
                    "inactive_role_positive_entries"
                ] += int(inactive_role_sum.item())

                if bool(active.any().item()):
                    active_source_count = source[active].sum(dim=1)
                    active_count = count[active]
                    label_violation_counts[
                        "active_source_count_mismatch"
                    ] += int(
                        (
                            active_source_count != active_count
                        ).sum().item()
                    )
                    label_violation_counts[
                        "active_category_count_mismatch"
                    ] += int(
                        (
                            active_count
                            != expected_category_count
                        ).sum().item()
                    )
                    label_violation_counts[
                        "active_missing_victim"
                    ] += int(
                        (
                            victim[active].sum(dim=1) == 0
                        ).sum().item()
                    )
                    label_violation_counts[
                        "active_missing_path"
                    ] += int(
                        (
                            path_label[active].sum(dim=1) == 0
                        ).sum().item()
                    )
                    label_violation_counts[
                        "active_missing_role_mask"
                    ] += int(
                        (
                            role_mask[active].sum(dim=1) == 0
                        ).sum().item()
                    )

                if mode == "control":
                    control_total = (
                        graph.sum()
                        + count.sum()
                        + source.sum()
                        + transit.sum()
                        + victim.sum()
                        + path_label.sum()
                        + role_mask.sum()
                    )
                    label_violation_counts[
                        "control_positive_label_entries"
                    ] += int(control_total.item())

                union_roles = (
                    (source > 0)
                    | (transit > 0)
                    | (victim > 0)
                )
                relation_counts[
                    "role_mask_equals_role_union_items"
                ] += int(
                    (
                        role_mask.bool() == union_roles
                    ).all(dim=1).sum().item()
                )
                relation_counts[
                    "path_equals_role_union_items"
                ] += int(
                    (
                        path_label.bool() == union_roles
                    ).all(dim=1).sum().item()
                )
                relation_counts[
                    "source_subset_of_path_items"
                ] += int(
                    (
                        (~source.bool())
                        | path_label.bool()
                    ).all(dim=1).sum().item()
                )
                relation_counts[
                    "victim_subset_of_path_items"
                ] += int(
                    (
                        (~victim.bool())
                        | path_label.bool()
                    ).all(dim=1).sum().item()
                )
                relation_counts["total_items"] += window_count

                targets_np = target_indices.cpu().numpy()
                progress = (
                    targets_np.astype(np.float64)
                    / max(1, common_length - 1)
                )
                common_lengths = np.full(
                    window_count,
                    common_length,
                    dtype=np.float64,
                )
                mode_values = np.full(
                    window_count,
                    1 if mode == "attack" else 0,
                    dtype=np.int64,
                )
                category_values = np.full(
                    window_count,
                    expected_category_count,
                    dtype=np.int64,
                )

                target_x = x[target_indices]
                status = target_x[:, :, 30]
                status_max = (
                    status.amax(dim=1).cpu().numpy()
                )
                status_mean = (
                    status.mean(dim=1).cpu().numpy()
                )
                traffic_score = target_x[:, :, 0:10].sum(dim=2)
                traffic_router = (
                    traffic_score.argmax(dim=1).cpu().numpy()
                )

                split_data[split]["graph"].append(
                    graph.cpu().numpy()
                )
                split_data[split]["count"].append(
                    count.cpu().numpy()
                )
                split_data[split]["source"].append(
                    source.cpu().numpy()
                )
                split_data[split]["transit"].append(
                    transit.cpu().numpy()
                )
                split_data[split]["victim"].append(
                    victim.cpu().numpy()
                )
                split_data[split]["path"].append(
                    path_label.cpu().numpy()
                )
                split_data[split]["role_mask"].append(
                    role_mask.cpu().numpy()
                )
                split_data[split]["mode"].append(mode_values)
                split_data[split]["category"].append(category_values)
                split_data[split]["progress"].append(progress)
                split_data[split]["common_length"].append(
                    common_lengths
                )
                split_data[split]["status_max"].append(status_max)
                split_data[split]["status_mean"].append(status_mean)
                split_data[split]["traffic_router"].append(
                    traffic_router
                )

                pair_member_window_counts[mode] = window_count
                pair_graph_positive[mode] = int(graph.sum().item())
                if mode == "attack":
                    pair_active_attack_windows = int(
                        active.sum().item()
                    )
                    pair_inactive_attack_windows = int(
                        inactive.sum().item()
                    )

                processed_windows[split] += window_count

            if (
                pair_member_window_counts.get("attack")
                != pair_member_window_counts.get("control")
            ):
                label_violation_counts[
                    "pair_member_window_count_mismatch"
                ] += 1

            pair_audit_rows.append(
                {
                    "split": split,
                    "pair_key": pair_key,
                    "category_count": expected_category_count,
                    "attack_length": attack_length,
                    "control_length": control_length,
                    "common_length": common_length,
                    "window_count_per_member": window_count,
                    "attack_graph_positive_windows": (
                        pair_graph_positive.get("attack")
                    ),
                    "control_graph_positive_windows": (
                        pair_graph_positive.get("control")
                    ),
                    "attack_active_windows": (
                        pair_active_attack_windows
                    ),
                    "attack_inactive_windows": (
                        pair_inactive_attack_windows
                    ),
                    "member_window_counts_equal": (
                        pair_member_window_counts.get("attack")
                        == pair_member_window_counts.get("control")
                    ),
                }
            )
            processed_pairs[split] += 1

            if row_index % 50 == 0 or row_index == len(rows):
                print(
                    f"{split}: audited {row_index}/{len(rows)} pairs"
                )

    # Turn per-member counts into total aligned item counts.
    expected_split_items = {
        "train": 70166,
        "validation": 12528,
    }
    for split in ("train", "validation"):
        if processed_pairs[split] != (
            415 if split == "train" else 74
        ):
            failures.append(
                f"{split} processed pair count="
                f"{processed_pairs[split]}"
            )
        if processed_runs[split] != (
            830 if split == "train" else 148
        ):
            failures.append(
                f"{split} processed run count="
                f"{processed_runs[split]}"
            )
        if processed_windows[split] != expected_split_items[split]:
            failures.append(
                f"{split} processed aligned items="
                f"{processed_windows[split]}, expected "
                f"{expected_split_items[split]}"
            )

    for key, count in label_violation_counts.items():
        if count != 0:
            failures.append(
                f"label integrity violation {key}={count}"
            )

    arrays: dict[str, dict[str, np.ndarray]] = {}
    for split in ("train", "validation"):
        arrays[split] = {}
        for key, parts in split_data[split].items():
            if not parts:
                failures.append(f"{split} has no collected {key}")
                continue
            arrays[split][key] = np.concatenate(parts, axis=0)

        lengths = {
            key: value.shape[0]
            for key, value in arrays[split].items()
        }
        if len(set(lengths.values())) != 1:
            failures.append(
                f"{split} collected array lengths disagree: {lengths}"
            )

    if failures:
        pair_csv_path = (
            output_dir
            / "V5_P2_B0_PAIR_LABEL_AUDIT.csv"
        )
        write_csv(pair_csv_path, pair_audit_rows)

        report = {
            "stage": STAGE,
            "status": "HOLD",
            "decision": "BLOCK_P2_B1",
            "processed_pairs": dict(processed_pairs),
            "processed_runs": dict(processed_runs),
            "processed_aligned_items": dict(processed_windows),
            "label_violation_counts": dict(label_violation_counts),
            "relation_counts": dict(relation_counts),
            "failures": failures,
            "warnings": warnings,
            "security_boundary": {
                "train_tensor_contents_accessed": True,
                "validation_tensor_contents_accessed": True,
                "test_directory_enumerated": False,
                "test_tensor_contents_accessed": False,
            },
            "next_stage": None,
        }
        write_json(output_dir / f"{STAGE}.json", report)
        atomic_write(
            output_dir / f"{STAGE}_HOLD",
            f"{STAGE}_HOLD\n",
        )
        print(f"{STAGE}_HOLD")
        for failure in failures[:100]:
            print("FAIL:", failure)
        print("failure_count:", len(failures))
        return 1

    train = arrays["train"]
    validation = arrays["validation"]

    train_active = train["graph"] == 1
    validation_active = validation["graph"] == 1

    # ------------------------------------------------------------------
    # Label summaries
    # ------------------------------------------------------------------
    label_summaries: dict[str, Any] = {}
    for split, data in arrays.items():
        active = data["graph"] == 1
        summary = {
            "items": int(data["graph"].shape[0]),
            "graph_negative": int((data["graph"] == 0).sum()),
            "graph_positive": int(active.sum()),
            "graph_positive_prevalence": float(active.mean()),
            "mode_control_items": int((data["mode"] == 0).sum()),
            "mode_attack_items": int((data["mode"] == 1).sum()),
            "active_count_distribution": {
                str(key): int(value)
                for key, value in zip(
                    *np.unique(
                        data["count"][active],
                        return_counts=True,
                    )
                )
            },
            "active_source_count_distribution": {
                str(key): int(value)
                for key, value in zip(
                    *np.unique(
                        data["source"][active].sum(axis=1),
                        return_counts=True,
                    )
                )
            },
            "active_victim_count_distribution": {
                str(key): int(value)
                for key, value in zip(
                    *np.unique(
                        data["victim"][active].sum(axis=1),
                        return_counts=True,
                    )
                )
            },
            "active_transit_count_distribution": {
                str(key): int(value)
                for key, value in zip(
                    *np.unique(
                        data["transit"][active].sum(axis=1),
                        return_counts=True,
                    )
                )
            },
            "active_path_count_distribution": {
                str(key): int(value)
                for key, value in zip(
                    *np.unique(
                        data["path"][active].sum(axis=1),
                        return_counts=True,
                    )
                )
            },
            "category_item_distribution": {
                str(key): int(value)
                for key, value in zip(
                    *np.unique(
                        data["category"],
                        return_counts=True,
                    )
                )
            },
        }
        label_summaries[split] = summary

    # ------------------------------------------------------------------
    # Graph baselines
    # ------------------------------------------------------------------
    baseline_rows: list[dict[str, Any]] = []
    baseline_details: dict[str, Any] = {}

    def record_graph_baseline(
        name: str,
        prediction: np.ndarray,
        family: str,
        learned_input_status: str,
        details: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        metrics = confusion_metrics(
            validation["graph"],
            prediction,
        )
        row = {
            "task": "graph",
            "baseline": name,
            "family": family,
            "learned_input_status": learned_input_status,
            **metrics,
        }
        baseline_rows.append(row)
        baseline_details[name] = {
            "metrics": metrics,
            "details": details or {},
        }
        return metrics

    always_normal = record_graph_baseline(
        "always_normal",
        np.zeros_like(validation["graph"]),
        "trivial",
        "none",
    )
    always_attack = record_graph_baseline(
        "always_attack",
        np.ones_like(validation["graph"]),
        "trivial",
        "none",
    )

    train_majority_label = int(
        train["graph"].mean() >= 0.5
    )
    train_majority = record_graph_baseline(
        "train_majority_graph",
        np.full_like(
            validation["graph"],
            train_majority_label,
        ),
        "trivial",
        "none",
        {"train_majority_label": train_majority_label},
    )

    mode_only = record_graph_baseline(
        "quarantined_mode_only",
        validation["mode"],
        "provenance_shortcut",
        "forbidden",
    )

    def threshold_graph_baseline(
        name: str,
        train_values: np.ndarray,
        validation_values: np.ndarray,
        family: str,
        learned_input_status: str,
    ) -> dict[str, Any]:
        fit = fit_threshold(
            train_values,
            train["graph"],
        )
        prediction = apply_threshold(
            validation_values,
            fit["threshold"],
            fit["direction"],
        )
        return record_graph_baseline(
            name,
            prediction,
            family,
            learned_input_status,
            {
                "threshold": fit["threshold"],
                "direction": fit["direction"],
                "train_metrics": fit["train_metrics"],
            },
        )

    epoch_position = threshold_graph_baseline(
        "forbidden_epoch_position_only",
        train["progress"],
        validation["progress"],
        "timing_shortcut",
        "forbidden",
    )
    common_length = threshold_graph_baseline(
        "forbidden_common_length_only",
        train["common_length"],
        validation["common_length"],
        "length_shortcut",
        "forbidden",
    )

    status_max_fit = fit_threshold(
        train["status_max"],
        train["graph"],
    )
    status_mean_fit = fit_threshold(
        train["status_mean"],
        train["graph"],
    )
    status_candidates = [
        ("max", status_max_fit),
        ("mean", status_mean_fit),
    ]
    status_summary_name, status_fit = max(
        status_candidates,
        key=lambda item: (
            item[1]["train_metrics"]["balanced_accuracy"],
            item[1]["train_metrics"]["f1"],
        ),
    )
    status_values = validation[
        "status_max" if status_summary_name == "max"
        else "status_mean"
    ]
    status_prediction = apply_threshold(
        status_values,
        status_fit["threshold"],
        status_fit["direction"],
    )
    status_only = record_graph_baseline(
        "quarantined_status_flags_only",
        status_prediction,
        "instrumentation_shortcut",
        "forbidden_and_excluded",
        {
            "summary": status_summary_name,
            "threshold": status_fit["threshold"],
            "direction": status_fit["direction"],
            "train_metrics": status_fit["train_metrics"],
        },
    )

    # ------------------------------------------------------------------
    # Count baselines, active windows only
    # ------------------------------------------------------------------
    train_active_counts = train["count"][train_active]
    validation_active_counts = validation["count"][
        validation_active
    ]
    count_values, count_frequencies = np.unique(
        train_active_counts,
        return_counts=True,
    )
    most_common_count = int(
        count_values[np.argmax(count_frequencies)]
    )
    count_prediction = np.full_like(
        validation_active_counts,
        most_common_count,
    )
    most_common_count_accuracy = float(
        (count_prediction == validation_active_counts).mean()
    )
    baseline_rows.append(
        {
            "task": "count_active",
            "baseline": "most_common_active_count",
            "family": "trivial",
            "learned_input_status": "none",
            "accuracy": most_common_count_accuracy,
            "predicted_count": most_common_count,
            "support": int(validation_active_counts.size),
        }
    )
    baseline_details["most_common_active_count"] = {
        "predicted_count": most_common_count,
        "validation_accuracy": most_common_count_accuracy,
    }

    category_count_accuracy = float(
        (
            validation["category"][validation_active]
            == validation_active_counts
        ).mean()
    )
    baseline_rows.append(
        {
            "task": "count_active",
            "baseline": "quarantined_category_only_count",
            "family": "provenance_shortcut",
            "learned_input_status": "forbidden",
            "accuracy": category_count_accuracy,
            "support": int(validation_active_counts.size),
        }
    )
    baseline_details["quarantined_category_only_count"] = {
        "validation_accuracy": category_count_accuracy,
    }

    # ------------------------------------------------------------------
    # Source trivial and traffic baselines, active windows only
    # ------------------------------------------------------------------
    train_active_source = train["source"][train_active]
    validation_active_source = validation["source"][
        validation_active
    ]

    train_source_frequency = train_active_source.sum(axis=0)
    most_common_source_node = int(
        np.argmax(train_source_frequency)
    )
    most_common_source_prediction = np.full(
        validation_active_source.shape[0],
        most_common_source_node,
        dtype=np.int64,
    )
    most_common_source_metrics = source_single_prediction_metrics(
        validation_active_source,
        most_common_source_prediction,
    )
    baseline_rows.append(
        {
            "task": "source_active",
            "baseline": "most_common_source_router",
            "family": "trivial_spatial_prior",
            "learned_input_status": (
                "router_identity_forbidden; audit_only"
            ),
            **most_common_source_metrics,
            "predicted_router": most_common_source_node,
        }
    )
    baseline_details["most_common_source_router"] = {
        "predicted_router": most_common_source_node,
        "train_source_frequency": (
            train_source_frequency.astype(int).tolist()
        ),
        "validation_metrics": most_common_source_metrics,
    }

    traffic_source_prediction = validation["traffic_router"][
        validation_active
    ]
    traffic_source_metrics = source_single_prediction_metrics(
        validation_active_source,
        traffic_source_prediction,
    )
    baseline_rows.append(
        {
            "task": "source_active",
            "baseline": "highest_final_epoch_traffic_router",
            "family": "observable_trivial_heuristic",
            "learned_input_status": "allowed_PRIMARY58",
            **traffic_source_metrics,
        }
    )
    baseline_details["highest_final_epoch_traffic_router"] = {
        "traffic_definition": (
            "argmax_router sum(final_epoch standardized "
            "in/out count channels 0..9)"
        ),
        "validation_metrics": traffic_source_metrics,
    }

    # ------------------------------------------------------------------
    # Physical-mask-only role priors, active windows only
    # ------------------------------------------------------------------
    signatures = mask_signature(physical_mask)
    mask_role_baselines: dict[str, Any] = {}

    for role in ("source", "transit", "victim", "path"):
        result = role_mask_prior_baseline(
            train[role][train_active],
            validation[role][validation_active],
            signatures,
        )
        mask_role_baselines[role] = result
        baseline_rows.append(
            {
                "task": f"{role}_active_node",
                "baseline": "physical_mask_only_role_prior",
                "family": "structural_shortcut",
                "learned_input_status": "allowed_topology_mask",
                "balanced_accuracy": (
                    result["validation_metrics"][
                        "balanced_accuracy"
                    ]
                ),
                "f1": result["validation_metrics"]["f1"],
                "precision": (
                    result["validation_metrics"]["precision"]
                ),
                "recall": result["validation_metrics"]["recall"],
                "fpr": result["validation_metrics"]["fpr"],
                "auroc": result["validation_auroc"],
                "average_precision": (
                    result["validation_average_precision"]
                ),
                "threshold": result["threshold"],
                "direction": result["direction"],
            }
        )

    baseline_details["physical_mask_only_role_priors"] = (
        mask_role_baselines
    )

    # ------------------------------------------------------------------
    # Shortcut interpretation
    # ------------------------------------------------------------------
    epoch_ba = epoch_position["balanced_accuracy"]
    if epoch_ba >= EPOCH_POSITION_BLOCK_BA:
        shortcut_blocks.append(
            "epoch-position-only graph balanced accuracy "
            f"{epoch_ba:.4f} >= {EPOCH_POSITION_BLOCK_BA:.2f}"
        )
    elif epoch_ba >= EPOCH_POSITION_WARN_BA:
        shortcut_warnings.append(
            "epoch-position-only graph balanced accuracy "
            f"{epoch_ba:.4f} >= {EPOCH_POSITION_WARN_BA:.2f}"
        )

    for role, result in mask_role_baselines.items():
        auc = result["validation_auroc"]
        if auc is None:
            continue
        if auc >= MASK_ROLE_BLOCK_AUROC:
            shortcut_blocks.append(
                f"physical-mask-only {role} AUROC "
                f"{auc:.4f} >= {MASK_ROLE_BLOCK_AUROC:.2f}"
            )
        elif auc >= MASK_ROLE_WARN_AUROC:
            shortcut_warnings.append(
                f"physical-mask-only {role} AUROC "
                f"{auc:.4f} >= {MASK_ROLE_WARN_AUROC:.2f}"
            )

    if (
        most_common_source_metrics["hit_at_1"]
        >= COMMON_SOURCE_WARN_HIT1
    ):
        shortcut_warnings.append(
            "most-common-source hit@1 "
            f"{most_common_source_metrics['hit_at_1']:.4f} >= "
            f"{COMMON_SOURCE_WARN_HIT1:.2f}"
        )

    if (
        traffic_source_metrics["hit_at_1"]
        >= TRAFFIC_SOURCE_WARN_HIT1
    ):
        shortcut_warnings.append(
            "highest-traffic-router source hit@1 "
            f"{traffic_source_metrics['hit_at_1']:.4f} >= "
            f"{TRAFFIC_SOURCE_WARN_HIT1:.2f}; treat as a required "
            "paper baseline, not leakage"
        )

    # Expected forbidden baselines are diagnostic only.
    diagnostic_notes = [
        (
            "Mode, category, status flags, run length, and epoch position "
            "remain forbidden learned inputs regardless of their scores."
        ),
        (
            "A strong highest-traffic-router result is an observable "
            "heuristic baseline and must be reported against the model."
        ),
        (
            "Physical mask is an authorized B3 input, so strong mask-only "
            "role AUROC indicates dataset spatial bias and is a blocker "
            "at the configured threshold."
        ),
    ]

    status = (
        "HOLD"
        if shortcut_blocks
        else "COMPLETE"
    )
    decision = (
        "BLOCK_P2_B1_FOR_SHORTCUT_REMEDIATION"
        if shortcut_blocks
        else "AUTHORIZE_P2_B1_TRAINING_PROTOCOL_LOCK"
    )
    next_stage = (
        None
        if shortcut_blocks
        else "V5_P2_B1_TRAINING_PROTOCOL_LOCK"
    )

    pair_csv_path = (
        output_dir
        / "V5_P2_B0_PAIR_LABEL_AUDIT.csv"
    )
    baseline_csv_path = (
        output_dir
        / "V5_P2_B0_TRIVIAL_AND_SHORTCUT_BASELINES.csv"
    )
    label_summary_path = (
        output_dir
        / "V5_P2_B0_LABEL_SUMMARY.json"
    )

    write_csv(pair_csv_path, pair_audit_rows)
    write_csv(baseline_csv_path, baseline_rows)
    write_json(
        label_summary_path,
        {
            "splits": label_summaries,
            "label_violation_counts": dict(
                label_violation_counts
            ),
            "label_relation_diagnostics": {
                key: {
                    "matching_items": int(value),
                    "total_items": int(
                        relation_counts["total_items"]
                    ),
                    "fraction": (
                        value
                        / max(
                            1,
                            relation_counts["total_items"],
                        )
                    ),
                }
                for key, value in relation_counts.items()
                if key != "total_items"
            },
        },
    )

    report = {
        "stage": STAGE,
        "status": status,
        "decision": decision,
        "dataset": {
            "link_path": str(root_input.absolute()),
            "resolved_root": str(root),
        },
        "coverage": {
            "train_pairs": int(processed_pairs["train"]),
            "validation_pairs": int(
                processed_pairs["validation"]
            ),
            "total_pairs": int(sum(processed_pairs.values())),
            "train_runs": int(processed_runs["train"]),
            "validation_runs": int(
                processed_runs["validation"]
            ),
            "total_runs": int(sum(processed_runs.values())),
            "train_aligned_items": int(
                processed_windows["train"]
            ),
            "validation_aligned_items": int(
                processed_windows["validation"]
            ),
            "total_aligned_items": int(
                sum(processed_windows.values())
            ),
        },
        "label_integrity": {
            "violation_counts": dict(label_violation_counts),
            "all_zero": not any(label_violation_counts.values()),
            "relation_diagnostics": {
                key: {
                    "matching_items": int(value),
                    "total_items": int(
                        relation_counts["total_items"]
                    ),
                    "fraction": (
                        value
                        / max(
                            1,
                            relation_counts["total_items"],
                        )
                    ),
                }
                for key, value in relation_counts.items()
                if key != "total_items"
            },
        },
        "label_summaries": label_summaries,
        "baselines": baseline_details,
        "shortcut_policy": {
            "epoch_position_block_balanced_accuracy": (
                EPOCH_POSITION_BLOCK_BA
            ),
            "epoch_position_warning_balanced_accuracy": (
                EPOCH_POSITION_WARN_BA
            ),
            "mask_role_block_auroc": MASK_ROLE_BLOCK_AUROC,
            "mask_role_warning_auroc": MASK_ROLE_WARN_AUROC,
            "common_source_warning_hit_at_1": (
                COMMON_SOURCE_WARN_HIT1
            ),
            "traffic_source_warning_hit_at_1": (
                TRAFFIC_SOURCE_WARN_HIT1
            ),
        },
        "shortcut_blocks": shortcut_blocks,
        "shortcut_warnings": shortcut_warnings,
        "diagnostic_notes": diagnostic_notes,
        "artifacts": {
            "pair_label_audit_csv": [
                str(pair_csv_path),
                sha256_file(pair_csv_path),
            ],
            "baseline_csv": [
                str(baseline_csv_path),
                sha256_file(baseline_csv_path),
            ],
            "label_summary_json": [
                str(label_summary_path),
                sha256_file(label_summary_path),
            ],
        },
        "provenance": {
            "a0_report_sha256": sha256_file(paths["a0_report"]),
            "a0_lock_sha256": sha256_file(paths["a0_lock"]),
            "a1_r2_report_sha256": sha256_file(
                paths["a1_r2_report"]
            ),
            "a1_r2_lock_sha256": sha256_file(
                paths["a1_r2_lock"]
            ),
            "pair_manifest_sha256": sha256_file(
                paths["pair_manifest"]
            ),
            "a2_r2_report_sha256": sha256_file(
                paths["a2_r2_report"]
            ),
            "a2_r2_lock_sha256": sha256_file(
                paths["a2_r2_lock"]
            ),
            "a2_r2_mask_sha256": sha256_file(
                paths["a2_r2_mask"]
            ),
            "a3_report_sha256": sha256_file(
                paths["a3_report"]
            ),
            "a3_lock_sha256": sha256_file(paths["a3_lock"]),
            "a4_report_sha256": sha256_file(
                paths["a4_report"]
            ),
            "a4_lock_sha256": sha256_file(paths["a4_lock"]),
            "loader_sha256": sha256_file(paths["loader"]),
        },
        "security_boundary": {
            "train_tensor_contents_accessed": True,
            "validation_tensor_contents_accessed": True,
            "test_directory_existence_checked": False,
            "test_directory_enumerated": False,
            "test_tensor_files_opened": False,
            "test_tensor_bytes_read": False,
            "test_tensor_contents_accessed": False,
            "test_dataset_constructed": False,
            "test_windows_constructed": False,
            "test_labels_read": False,
        },
        "failures": failures,
        "warnings": warnings + shortcut_warnings,
        "next_stage": next_stage,
    }

    report_path = output_dir / f"{STAGE}.json"
    write_json(report_path, report)

    if status == "HOLD":
        atomic_write(
            output_dir / f"{STAGE}_HOLD",
            f"{STAGE}_HOLD\n",
        )
        print("===== V5 P2-B0 FINAL =====")
        print("status: HOLD")
        print("decision:", decision)
        print("label_integrity_pass: true")
        print("shortcut_block_count:", len(shortcut_blocks))
        for item in shortcut_blocks:
            print("SHORTCUT_BLOCK:", item)
        print("shortcut_warning_count:", len(shortcut_warnings))
        for item in shortcut_warnings:
            print("SHORTCUT_WARNING:", item)
        print("test_directory_enumerated: false")
        print("test_tensor_contents_accessed: false")
        print(f"{STAGE}_HOLD")
        return 1

    lock = {
        "status": COMPLETE,
        "decision": decision,
        "report_sha256": sha256_file(report_path),
        "pair_label_audit_sha256": sha256_file(pair_csv_path),
        "baseline_csv_sha256": sha256_file(baseline_csv_path),
        "label_summary_sha256": sha256_file(label_summary_path),
        "total_pairs": int(sum(processed_pairs.values())),
        "total_runs": int(sum(processed_runs.values())),
        "total_aligned_items": int(sum(processed_windows.values())),
        "label_integrity_pass": True,
        "label_violation_counts": dict(label_violation_counts),
        "shortcut_block_count": 0,
        "shortcut_warning_count": len(shortcut_warnings),
        "epoch_position_validation_balanced_accuracy": (
            epoch_position["balanced_accuracy"]
        ),
        "mask_role_validation_auroc": {
            role: result["validation_auroc"]
            for role, result in mask_role_baselines.items()
        },
        "most_common_source_validation_hit_at_1": (
            most_common_source_metrics["hit_at_1"]
        ),
        "highest_traffic_source_validation_hit_at_1": (
            traffic_source_metrics["hit_at_1"]
        ),
        "test_directory_enumerated": False,
        "test_tensor_contents_accessed": False,
        "next_stage": next_stage,
        "script_sha256": sha256_file(Path(__file__)),
    }
    write_json(output_dir / f"{STAGE}_LOCK.json", lock)
    atomic_write(output_dir / COMPLETE, COMPLETE + "\n")

    print("===== V5 P2-B0 FINAL =====")
    print("status: COMPLETE")
    print("decision:", decision)
    print("train_pairs:", processed_pairs["train"])
    print("validation_pairs:", processed_pairs["validation"])
    print("total_pairs:", sum(processed_pairs.values()))
    print("total_runs:", sum(processed_runs.values()))
    print("train_aligned_items:", processed_windows["train"])
    print(
        "validation_aligned_items:",
        processed_windows["validation"],
    )
    print("total_aligned_items:", sum(processed_windows.values()))
    print("label_integrity_pass: true")
    print("label_violation_count: 0")
    print(
        "graph_validation_prevalence:",
        f"{label_summaries['validation']['graph_positive_prevalence']:.10g}",
    )
    print(
        "always_normal_validation_balanced_accuracy:",
        f"{always_normal['balanced_accuracy']:.10g}",
    )
    print(
        "epoch_position_validation_balanced_accuracy:",
        f"{epoch_position['balanced_accuracy']:.10g}",
    )
    print(
        "common_length_validation_balanced_accuracy:",
        f"{common_length['balanced_accuracy']:.10g}",
    )
    print(
        "quarantined_status_validation_balanced_accuracy:",
        f"{status_only['balanced_accuracy']:.10g}",
    )
    print(
        "quarantined_mode_validation_balanced_accuracy:",
        f"{mode_only['balanced_accuracy']:.10g}",
    )
    print(
        "most_common_count_validation_accuracy:",
        f"{most_common_count_accuracy:.10g}",
    )
    print(
        "quarantined_category_count_validation_accuracy:",
        f"{category_count_accuracy:.10g}",
    )
    print(
        "most_common_source_validation_hit_at_1:",
        f"{most_common_source_metrics['hit_at_1']:.10g}",
    )
    print(
        "highest_traffic_source_validation_hit_at_1:",
        f"{traffic_source_metrics['hit_at_1']:.10g}",
    )
    for role in ("source", "transit", "victim", "path"):
        print(
            f"mask_only_{role}_validation_auroc:",
            mask_role_baselines[role]["validation_auroc"],
        )
    print("shortcut_block_count: 0")
    print("shortcut_warning_count:", len(shortcut_warnings))
    for item in shortcut_warnings:
        print("SHORTCUT_WARNING:", item)
    print("test_directory_enumerated: false")
    print("test_tensor_contents_accessed: false")
    print("failure_count:", len(failures))
    print(
        "warning_count:",
        len(warnings) + len(shortcut_warnings),
    )
    print("next_stage:", next_stage)
    print(COMPLETE)
    return 0

def evaluate(
    outputs: dict[str, torch.Tensor],
    batch: dict[str, torch.Tensor],
    count_targets: torch.Tensor,
    active_mask: torch.Tensor,
) -> dict[str, Any]:
    graph = exact_binary_metrics(
        outputs["attack_logits"],
        batch["y_attack"],
    )

    active_count_prediction = outputs["count_logits"][
        active_mask
    ].argmax(dim=-1)
    active_count_truth = count_targets[active_mask]
    count_accuracy = float(
        (
            active_count_prediction == active_count_truth
        ).float().mean().item()
    )
    count_all_exact = bool(
        (
            active_count_prediction == active_count_truth
        ).all().item()
    )

    roles = {}
    for logical, output_key, target_key in (
        ("source", "source_logits", "y_source"),
        ("transit", "transit_logits", "y_transit"),
        ("victim", "victim_logits", "y_victim"),
        ("path", "path_logits", "y_attack_path"),
    ):
        roles[logical] = exact_binary_metrics(
            outputs[output_key],
            batch[target_key],
        )

    all_exact = (
        graph["all_exact"]
        and count_all_exact
        and all(item["all_exact"] for item in roles.values())
    )

    return {
        "graph": graph,
        "count_active_accuracy": count_accuracy,
        "count_all_exact": count_all_exact,
        "roles": roles,
        "all_tasks_all_exact": all_exact,
    }

def evaluate(
    outputs: dict[str, torch.Tensor],
    batch: dict[str, torch.Tensor],
    count_targets: torch.Tensor,
    active_mask: torch.Tensor,
) -> dict[str, Any]:
    graph = exact_binary_metrics(
        outputs["attack_logits"],
        batch["y_attack"],
    )

    count_prediction = outputs[
        "count_logits"
    ][active_mask].argmax(dim=-1)
    count_truth = count_targets[active_mask]
    count_exact = count_prediction == count_truth

    roles = {}
    for logical, output_key, target_key in (
        (
            "source",
            "source_logits",
            "y_source",
        ),
        (
            "transit",
            "transit_logits",
            "y_transit",
        ),
        (
            "victim",
            "victim_logits",
            "y_victim",
        ),
        (
            "path",
            "path_logits",
            "y_attack_path",
        ),
    ):
        roles[logical] = exact_binary_metrics(
            outputs[output_key],
            batch[target_key],
        )

    all_exact = (
        graph["all_exact"]
        and bool(count_exact.all().item())
        and all(
            value["all_exact"]
            for value in roles.values()
        )
    )

    return {
        "graph": graph,
        "count_active_accuracy": float(
            count_exact.float().mean().item()
        ),
        "count_all_exact": bool(
            count_exact.all().item()
        ),
        "roles": roles,
        "all_tasks_all_exact": all_exact,
    }

top_loader_callables.source:
def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--root",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--a1-r2-dir",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--a3-dir",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--a4-dir",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--b0-r1b-dir",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--loader-path",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--model-path",
        type=Path,
        required=True,
    )
    parser.add_argument(
        "--output-dir",
        type=Path,
        required=True,
    )
    args = parser.parse_args()

    root_input = args.root.expanduser()
    root = root_input.resolve()
    a1_r2_dir = args.a1_r2_dir.expanduser().resolve()
    a3_dir = args.a3_dir.expanduser().resolve()
    a4_dir = args.a4_dir.expanduser().resolve()
    b0_r1b_dir = (
        args.b0_r1b_dir.expanduser().resolve()
    )
    loader_path = (
        args.loader_path.expanduser().resolve()
    )
    model_path = (
        args.model_path.expanduser().resolve()
    )
    output_dir = (
        args.output_dir.expanduser().resolve()
    )

    if output_dir.exists():
        print(
            f"STOP: output already exists: "
            f"{output_dir}",
            file=sys.stderr,
        )
        return 2
    output_dir.mkdir(parents=True)

    failures: list[str] = []
    warnings: list[str] = []

    paths = {
        "a1_r2_report": (
            a1_r2_dir
            / "V5_P2_A1_R2_PAIR_ALIGNED_WINDOW_CONTRACT.json"
        ),
        "a1_r2_lock": (
            a1_r2_dir
            / "V5_P2_A1_R2_PAIR_ALIGNED_WINDOW_CONTRACT_LOCK.json"
        ),
        "pair_manifest": (
            a1_r2_dir
            / "V5_P2_A1_R2_PAIR_ALIGNED_WINDOW_MANIFEST.csv"
        ),
        "a3_report": (
            a3_dir
            / "V5_P2_A3_PAIR_ALIGNED_PRIMARY58_LOADER_CONTRACT.json"
        ),
        "a3_lock": (
            a3_dir
            / "V5_P2_A3_PAIR_ALIGNED_PRIMARY58_LOADER_CONTRACT_LOCK.json"
        ),
        "a4_report": (
            a4_dir
            / "V5_P2_A4_LOADER_INTEGRATION_AND_TINY_OVERFIT.json"
        ),
        "a4_lock": (
            a4_dir
            / "V5_P2_A4_LOADER_INTEGRATION_AND_TINY_OVERFIT_LOCK.json"
        ),
        "b0_r1b_report": (
            b0_r1b_dir
            / "V5_P2_B0_R1B_K3_COUNT_AND_ROLE_MASK_SEMANTICS_AUDIT.json"
        ),
        "b0_r1b_lock": (
            b0_r1b_dir
            / "V5_P2_B0_R1B_K3_COUNT_AND_ROLE_MASK_SEMANTICS_AUDIT_LOCK.json"
        ),
        "loader": loader_path,
        "model": model_path,
    }

    for name, path in paths.items():
        if not path.is_file():
            failures.append(
                f"missing prerequisite {name}: {path}"
            )

    if not (
        root
        / "runs"
        / "train"
    ).is_dir():
        failures.append(
            "missing runs/train"
        )

    if failures:
        report = {
            "stage": STAGE,
            "status": "HOLD",
            "failures": failures,
            "warnings": warnings,
            "training_performed": False,
            "validation_tensor_contents_accessed": False,
            "test_directory_enumerated": False,
            "test_tensor_contents_accessed": False,
        }
        write_json(
            output_dir / f"{STAGE}.json",
            report,
        )
        atomic_write(
            output_dir / f"{STAGE}_HOLD",
            f"{STAGE}_HOLD\n",
        )
        print(f"{STAGE}_HOLD")
        return 1

    a1_report = load_json(
        paths["a1_r2_report"]
    )
    a1_lock = load_json(
        paths["a1_r2_lock"]
    )
    a3_report = load_json(
        paths["a3_report"]
    )
    a3_lock = load_json(
        paths["a3_lock"]
    )
    a4_report = load_json(
        paths["a4_report"]
    )
    a4_lock = load_json(
        paths["a4_lock"]
    )
    b0_r1b_report = load_json(
        paths["b0_r1b_report"]
    )
    b0_r1b_lock = load_json(
        paths["b0_r1b_lock"]
    )

    for label, report, lock, report_path in (
        (
            "A1-R2",
            a1_report,
            a1_lock,
            paths["a1_r2_report"],
        ),
        (
            "A3",
            a3_report,
            a3_lock,
            paths["a3_report"],
        ),
        (
            "A4",
            a4_report,
            a4_lock,
            paths["a4_report"],
        ),
        (
            "B0-R1B",
            b0_r1b_report,
            b0_r1b_lock,
            paths["b0_r1b_report"],
        ),
    ):
        if report.get("status") != "COMPLETE":
            failures.append(
                f"{label} status is not COMPLETE"
            )
        if (
            lock.get("report_sha256")
            != sha256_file(report_path)
        ):
            failures.append(
                f"{label} report SHA mismatch"
            )
        if (
            report.get(
                "security_boundary",
                {},
            ).get(
                "test_tensor_contents_accessed"
            )
            is not False
        ):
            failures.append(
                f"{label} does not certify untouched test"
            )

    expected_b0_r1b_decision = (
        "RESOLVE_B0_HOLD_AS_K3_OMISSION_AND_"
        "ROLE_MASK_SEMANTIC_MISCLASSIFICATION_"
        "REQUIRE_COUNT_HEAD_3_TO_4_AND_REPEAT_A4"
    )
    if (
        b0_r1b_lock.get("decision")
        != expected_b0_r1b_decision
    ):
        failures.append(
            "B0-R1B did not authorize count-head "
            "expansion and A4 repeat"
        )
    if b0_r1b_lock.get(
        "observed_categories"
    ) != [1, 2, 3, 4]:
        failures.append(
            "B0-R1B observed categories changed"
        )
    if b0_r1b_lock.get(
        "observed_active_counts"
    ) != [1, 2, 3, 4]:
        failures.append(
            "B0-R1B observed active counts changed"
        )
    if b0_r1b_lock.get(
        "role_mask_semantics"
    ) != "bitfield3_source1_transit2_victim4":
        failures.append(
            "B0-R1B role_mask semantics changed"
        )
    if b0_r1b_lock.get(
        "current_count_logits"
    ) != 3:
        failures.append(
            "B0-R1B current count logits changed"
        )
    if b0_r1b_lock.get(
        "required_count_logits"
    ) != 4:
        failures.append(
            "B0-R1B required count logits changed"
        )
    if b0_r1b_lock.get(
        "projected_parameter_count"
    ) != EXPECTED_PARAMETER_COUNT:
        failures.append(
            "B0-R1B projected parameter count changed"
        )

    if (
        a1_lock.get("pair_manifest_sha256")
        != sha256_file(paths["pair_manifest"])
    ):
        failures.append(
            "A1-R2 pair-manifest SHA mismatch"
        )
    if (
        a3_lock.get("loader_sha256")
        != sha256_file(paths["loader"])
    ):
        failures.append(
            "A3 loader SHA mismatch"
        )
    if a3_lock.get(
        "test_constructor_rejected"
    ) is not True:
        failures.append(
            "A3 test-constructor rejection changed"
        )
    if a4_lock.get(
        "audit_weights_saved"
    ) is not False:
        failures.append(
            "historical A4 unexpectedly saved weights"
        )

    if failures:
        report = {
            "stage": STAGE,
            "status": "HOLD",
            "failures": failures,
            "warnings": warnings,
            "training_performed": False,
            "validation_tensor_contents_accessed": False,
            "test_directory_enumerated": False,
            "test_tensor_contents_accessed": False,
        }
        write_json(
            output_dir / f"{STAGE}.json",
            report,
        )
        atomic_write(
            output_dir / f"{STAGE}_HOLD",
            f"{STAGE}_HOLD\n",
        )
        print(f"{STAGE}_HOLD")
        for failure in failures:
            print("FAIL:", failure)
        return 1

    set_seed(SEED)

    loader_module = import_module(
        loader_path,
        "v5_p2_pair_aligned_loader_b0_r2",
    )
    model_module = import_module(
        model_path,
        "v5_p2_b3_count4_b0_r2",
    )

    DatasetClass = (
        loader_module
        .V5P2PairAlignedPrimary58Dataset
    )
    ModelClass = (
        model_module
        .P2B3Conv1DOnlyCount4
    )

    train_dataset = DatasetClass(
        root=root,
        split="train",
        pair_manifest=paths["pair_manifest"],
    )

    pair_bases: dict[
        str,
        list[int],
    ] = defaultdict(list)

    for base in range(
        0,
        len(train_dataset._index),
        2,
    ):
        attack_entry = train_dataset._index[base]
        control_entry = train_dataset._index[
            base + 1
        ]

        if (
            attack_entry.mode != "attack"
            or control_entry.mode != "control"
            or attack_entry.pair_key
            != control_entry.pair_key
            or attack_entry.start
            != control_entry.start
            or attack_entry.target
            != control_entry.target
        ):
            failures.append(
                f"train pair-index adjacency failed "
                f"at base={base}"
            )
            continue

        pair_bases[
            attack_entry.pair_key
        ].append(base)

    selected_by_category: dict[
        int,
        list[dict[str, Any]],
    ] = defaultdict(list)

    for pair_key in sorted(pair_bases):
        category = category_from_pair_key(
            pair_key
        )
        if category not in {
            1,
            2,
            3,
            4,
        }:
            continue
        if len(
            selected_by_category[category]
        ) >= 2:
            continue

        bases = pair_bases[pair_key]
        first_entry = train_dataset._index[
            bases[0]
        ]
        attack_run = train_dataset._load_run(
            first_entry.file_path
        )

        active_bases = [
            base
            for base in bases
            if int(
                attack_run["y_attack"][
                    train_dataset._index[
                        base
                    ].target
                ].item()
            )
            == 1
        ]
        if not active_bases:
            continue

        base = active_bases[-1]
        attack_entry = train_dataset._index[
            base
        ]
        control_entry = train_dataset._index[
            base + 1
        ]

        attack_item = train_dataset[base]
        control_item = train_dataset[
            base + 1
        ]

        raw_count = int(
            attack_item[
                "y_attacker_count"
            ].item()
        )
        source_count = int(
            attack_item[
                "y_source"
            ].sum().item()
        )

        if float(
            attack_item["y_attack"].item()
        ) != 1.0:
            failures.append(
                f"{pair_key}: selected attack is inactive"
            )
            continue
        if float(
            control_item["y_attack"].item()
        ) != 0.0:
            failures.append(
                f"{pair_key}: matched control is active"
            )
            continue
        if raw_count != category:
            failures.append(
                f"{pair_key}: attack count={raw_count}, "
                f"category={category}"
            )
            continue
        if source_count != category:
            failures.append(
                f"{pair_key}: source count="
                f"{source_count}, category={category}"
            )
            continue
        if int(
            control_item[
                "y_attacker_count"
            ].item()
        ) != 0:
            failures.append(
                f"{pair_key}: control count is nonzero"
            )
            continue

        selected_by_category[
            category
        ].append(
            {
                "category": category,
                "pair_key": pair_key,
                "attack_index": base,
                "control_index": base + 1,
                "window_start": (
                    attack_entry.start
                ),
                "window_target": (
                    attack_entry.target
                ),
                "common_length": (
                    attack_entry.common_length
                ),
                "raw_positive_attacker_count": (
                    raw_count
                ),
            }
        )

        if all(
            len(
                selected_by_category[
                    category_value
                ]
            )
            >= 2
            for category_value in (
                1,
                2,
                3,
                4,
            )
        ):
            break

    for category in (1, 2, 3, 4):
        if len(
            selected_by_category[category]
        ) != 2:
            failures.append(
                f"selected "
                f"{len(selected_by_category[category])} "
                f"active K{category} pairs, expected 2"
            )

    selected_pairs = [
        record
        for category in (1, 2, 3, 4)
        for record in selected_by_category[
            category
        ]
    ]

    selected_indices: list[int] = []
    for record in selected_pairs:
        selected_indices.extend(
            [
                record["attack_index"],
                record["control_index"],
            ]
        )

    if len(selected_pairs) != 8:
        failures.append(
            f"selected pair count="
            f"{len(selected_pairs)}, expected 8"
        )
    if len(selected_indices) != 16:
        failures.append(
            f"tiny item count="
            f"{len(selected_indices)}, expected 16"
        )

    if failures:
        report = {
            "stage": STAGE,
            "status": "HOLD",
            "failures": failures,
            "warnings": warnings,
            "selection": selected_pairs,
            "training_performed": False,
            "validation_tensor_contents_accessed": False,
            "test_directory_enumerated": False,
            "test_tensor_contents_accessed": False,
        }
        write_json(
            output_dir / f"{STAGE}.json",
            report,
        )
        atomic_write(
            output_dir / f"{STAGE}_HOLD",
            f"{STAGE}_HOLD\n",
        )
        print(f"{STAGE}_HOLD")
        for failure in failures:
            print("FAIL:", failure)
        return 1

    subset = Subset(
        train_dataset,
        selected_indices,
    )
    batch_loader = DataLoader(
        subset,
        batch_size=len(subset),
        shuffle=False,
        num_workers=0,
        drop_last=False,
    )
    batch = next(iter(batch_loader))

    expected_batch_keys = {
        "x",
        "physical_port_mask",
        "y_attack",
        "y_attacker_count",
        "y_source",
        "y_transit",
        "y_victim",
        "y_attack_path",
        "role_mask",
    }
    if set(batch) != expected_batch_keys:
        failures.append(
            f"collated keys={sorted(batch)}, "
            f"expected={sorted(expected_batch_keys)}"
        )
    if tuple(
        batch["x"].shape
    ) != (16, 16, 58, 32):
        failures.append(
            f"collated x shape="
            f"{tuple(batch['x'].shape)}"
        )
    if tuple(
        batch[
            "physical_port_mask"
        ].shape
    ) != (16, 16, 10):
        failures.append(
            "collated physical-port-mask "
            "shape mismatch"
        )

    expected_role_mask = (
        batch["y_source"].to(torch.int64)
        + 2
        * batch["y_transit"].to(
            torch.int64
        )
        + 4
        * batch["y_victim"].to(
            torch.int64
        )
    )
    actual_role_mask = batch[
        "role_mask"
    ].to(torch.int64)

    role_mask_mismatch_count = int(
        (
            actual_role_mask
            != expected_role_mask
        ).sum().item()
    )
    if role_mask_mismatch_count != 0:
        failures.append(
            f"tiny batch role_mask bit-field "
            f"mismatches={role_mask_mismatch_count}"
        )

    device = torch.device(
        "cuda"
        if torch.cuda.is_available()
        else "cpu"
    )
    batch = {
        key: value.to(device)
        for key, value in batch.items()
    }

    active_mask = (
        batch["y_attack"] >= 0.5
    )
    if int(
        active_mask.sum().item()
    ) != 8:
        failures.append(
            f"active item count="
            f"{int(active_mask.sum().item())}, "
            "expected 8"
        )

    count_class_mapping = {
        raw_count: class_index
        for class_index, raw_count in enumerate(
            EXPECTED_COUNT_CLASS_VALUES
        )
    }
    count_targets = torch.full(
        batch[
            "y_attacker_count"
        ].shape,
        fill_value=-100,
        dtype=torch.int64,
        device=device,
    )

    for raw_count, class_index in (
        count_class_mapping.items()
    ):
        selector = (
            active_mask
            & (
                batch[
                    "y_attacker_count"
                ]
                == raw_count
            )
        )
        count_targets[selector] = class_index

    if bool(
        (
            count_targets[active_mask]
            < 0
        ).any().item()
    ):
        failures.append(
            "one or more active count targets "
            "were not mapped"
        )

    active_raw_counts = sorted(
        int(value)
        for value in torch.unique(
            batch[
                "y_attacker_count"
            ][active_mask]
        ).tolist()
    )
    if (
        active_raw_counts
        != EXPECTED_COUNT_CLASS_VALUES
    ):
        failures.append(
            f"tiny batch active raw counts="
            f"{active_raw_counts}, expected "
            f"{EXPECTED_COUNT_CLASS_VALUES}"
        )

    model = ModelClass().to(device)
    parameter_count = sum(
        parameter.numel()
        for parameter in model.parameters()
    )
    trainable_parameter_count = sum(
        parameter.numel()
        for parameter in model.parameters()
        if parameter.requires_grad
    )

    if (
        parameter_count
        != EXPECTED_PARAMETER_COUNT
    ):
        failures.append(
            f"model parameter count="
            f"{parameter_count}, expected "
            f"{EXPECTED_PARAMETER_COUNT}"
        )
    if (
        trainable_parameter_count
        != EXPECTED_PARAMETER_COUNT
    ):
        failures.append(
            f"trainable parameter count="
            f"{trainable_parameter_count}, expected "
            f"{EXPECTED_PARAMETER_COUNT}"
        )
    if model.count_head.out_features != 4:
        failures.append(
            "P2 count head does not have 4 logits"
        )
    if list(
        model.count_class_values
    ) != EXPECTED_COUNT_CLASS_VALUES:
        failures.append(
            "model count-class values changed"
        )

    with torch.no_grad():
        shape_outputs = model(
            batch["x"],
            batch["physical_port_mask"],
        )

    expected_output_shapes = {
        "attack_logits": (16,),
        "count_logits": (16, 4),
        "source_logits": (16, 16),
        "transit_logits": (16, 16),
        "victim_logits": (16, 16),
        "path_logits": (16, 16),
    }
    for key, expected_shape in (
        expected_output_shapes.items()
    ):
        if tuple(
            shape_outputs[key].shape
        ) != expected_shape:
            failures.append(
                f"{key} shape="
                f"{tuple(shape_outputs[key].shape)}, "
                f"expected {expected_shape}"
            )

    if failures:
        report = {
            "stage": STAGE,
            "status": "HOLD",
            "failures": failures,
            "warnings": warnings,
            "selection": selected_pairs,
            "training_performed": False,
            "validation_tensor_contents_accessed": False,
            "test_directory_enumerated": False,
            "test_tensor_contents_accessed": False,
        }
        write_json(
            output_dir / f"{STAGE}.json",
            report,
        )
        atomic_write(
            output_dir / f"{STAGE}_HOLD",
            f"{STAGE}_HOLD\n",
        )
        print(f"{STAGE}_HOLD")
        for failure in failures:
            print("FAIL:", failure)
        return 1

    graph_pos_weight = positive_weight(
        batch["y_attack"]
    )
    role_pos_weights = {
        "source": positive_weight(
            batch["y_source"]
        ),
        "transit": positive_weight(
            batch["y_transit"]
        ),
        "victim": positive_weight(
            batch["y_victim"]
        ),
        "path": positive_weight(
            batch["y_attack_path"]
        ),
    }

    optimizer = torch.optim.Adam(
        model.parameters(),
        lr=LEARNING_RATE,
    )

    history: list[dict[str, Any]] = []
    initial_loss = None
    final_loss = None
    final_metrics = None
    completed_step = 0
    stable_exact_steps = 0
    maximum_gradient_norm = 0.0
    maximum_nonzero_gradient_tensors = 0

    def compute_loss(
        outputs: dict[str, torch.Tensor],
    ) -> tuple[
        torch.Tensor,
        dict[str, torch.Tensor],
    ]:
        components = {
            "attack": (
                F.binary_cross_entropy_with_logits(
                    outputs["attack_logits"],
                    batch["y_attack"].float(),
                    pos_weight=graph_pos_weight,
                )
            ),
            "count": (
                F.cross_entropy(
                    outputs[
                        "count_logits"
                    ][active_mask],
                    count_targets[active_mask],
                )
            ),
            "source": (
                F.binary_cross_entropy_with_logits(
                    outputs["source_logits"],
                    batch["y_source"].float(),
                    pos_weight=role_pos_weights[
                        "source"
                    ],
                )
            ),
            "transit": (
                F.binary_cross_entropy_with_logits(
                    outputs["transit_logits"],
                    batch["y_transit"].float(),
                    pos_weight=role_pos_weights[
                        "transit"
                    ],
                )
            ),
            "victim": (
                F.binary_cross_entropy_with_logits(
                    outputs["victim_logits"],
                    batch["y_victim"].float(),
                    pos_weight=role_pos_weights[
                        "victim"
                    ],
                )
            ),
            "path": (
                F.binary_cross_entropy_with_logits(
                    outputs["path_logits"],
                    batch[
                        "y_attack_path"
                    ].float(),
                    pos_weight=role_pos_weights[
                        "path"
                    ],
                )
            ),
        }

        total = sum(
            LOSS_WEIGHTS[key]
            * value
            for key, value in components.items()
        )
        return total, components

    for step in range(
        1,
        MAX_STEPS + 1,
    ):
        model.train()
        optimizer.zero_grad(
            set_to_none=True
        )

        outputs = model(
            batch["x"],
            batch["physical_port_mask"],
        )
        loss, components = compute_loss(
            outputs
        )

        if not torch.isfinite(loss):
            failures.append(
                f"non-finite loss at step {step}"
            )
            break

        if initial_loss is None:
            initial_loss = float(
                loss.item()
            )

        loss.backward()

        squared_norm = 0.0
        nonzero_gradient_tensors = 0
        for parameter in model.parameters():
            if parameter.grad is None:
                continue

            gradient = parameter.grad.detach()
            squared_norm += float(
                gradient.float()
                .pow(2)
                .sum()
                .item()
            )
            if bool(
                (gradient != 0).any().item()
            ):
                nonzero_gradient_tensors += 1

        gradient_norm = math.sqrt(
            squared_norm
        )
        maximum_gradient_norm = max(
            maximum_gradient_norm,
            gradient_norm,
        )
        maximum_nonzero_gradient_tensors = max(
            maximum_nonzero_gradient_tensors,
            nonzero_gradient_tensors,
        )

        optimizer.step()

        model.eval()
        with torch.no_grad():
            current_outputs = model(
                batch["x"],
                batch[
                    "physical_port_mask"
                ],
            )
            current_loss, current_components = (
                compute_loss(current_outputs)
            )
            metrics = evaluate(
                current_outputs,
                batch,
                count_targets,
                active_mask,
            )

        completed_step = step
        final_loss = float(
            current_loss.item()
        )
        final_metrics = metrics

        if (
            metrics[
                "all_tasks_all_exact"
            ]
            and final_loss <= 0.05
        ):
            stable_exact_steps += 1
        else:
            stable_exact_steps = 0

        if (
            step == 1
            or step % 25 == 0
            or stable_exact_steps > 0
        ):
            history.append(
                {
                    "step": step,
                    "loss": final_loss,
                    "attack_loss": float(
                        current_components[
                            "attack"
                        ].item()
                    ),
                    "count_loss": float(
                        current_components[
                            "count"
                        ].item()
                    ),
                    "source_loss": float(
                        current_components[
                            "source"
                        ].item()
                    ),
                    "transit_loss": float(
                        current_components[
                            "transit"
                        ].item()
                    ),
                    "victim_loss": float(
                        current_components[
                            "victim"
                        ].item()
                    ),
                    "path_loss": float(
                        current_components[
                            "path"
                        ].item()
                    ),
                    "gradient_norm_before_step": (
                        gradient_norm
                    ),
                    "graph_all_exact": (
