                            "graph"
                        ][
                            "all_exact"
                        ]
                    ),
                    "count_all_exact": (
                        metrics[
                            "count_all_exact"
                        ]
                    ),
                    "count_active_accuracy": (
                        metrics[
                            "count_active_accuracy"
                        ]
                    ),
                    "source_all_exact": (
                        metrics[
                            "roles"
                        ][
                            "source"
                        ][
                            "all_exact"
                        ]
                    ),
                    "transit_all_exact": (
                        metrics[
