            ),
            "a2_r2_lock_sha256": sha256_file(
                paths["a2_r2_lock"]
            ),
            "a2_r2_mask_sha256": sha256_file(
                paths["a2_r2_mask"]
            ),
            "a3_report_sha256": sha256_file(
                paths["a3_report"]
            ),
            "a3_lock_sha256": sha256_file(paths["a3_lock"]),
            "b0_r1b_report_sha256": sha256_file(
                paths["b0_r1b_report"]
            ),
            "b0_r1b_lock_sha256": sha256_file(
