        print("shortcut_warning_count:", len(shortcut_warnings))
        for item in shortcut_warnings:
            print("SHORTCUT_WARNING:", item)
        print("test_directory_enumerated: false")
        print("test_tensor_contents_accessed: false")
        print(f"{STAGE}_HOLD")
        return 1

